WITH payload AS (SELECT $archive_payload$[{"id":"0d49a3b8-aca8-5a5e-9c35-234c134a0ec7","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج -احلبوب احملظورة -إنكار املدعى عليه تقرير كيميائي -عدم ثبوت االدانة لعدم البينة -عدم حضور","document_number":"34341462","case_number":"33608728","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/26","year":"1434","subject":"مخدرات -ترويج -احلبوب احملظورة -إنكار املدعى عليه تقرير كيميائي -عدم ثبوت االدانة لعدم البينة -عدم حضور","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34341462:‬تاريخه‪1434/10/26 :‬هـ‬\n                          ‫رقم الدعوى‪33608728:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34382742‬تاريخه‪1434/12/19:‬هـ‬\n\n\n       ‫حتقيقــا‪-‬‬\n           ‫ً‬     ‫مخــدرات ‪ -‬ترويــج ‪ -‬احلبــوب احملظــورة ‪ -‬إنــكار املدعــى عليــه‬\n       ‫تقريــر كيميائــي‪ -‬عــدم ثبــوت االدانــة لعــدم البينــة‪ -‬عــدم حضــور‬\n                                                                            ‫البينــة‪.‬‬\n\n\n\n\n       ‫‪ -‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬والفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام‬\n                                        ‫مكافحــة املخــدرات واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n       ‫‪ -‬قــول الفقهــاء‪ :‬وال يجــوز للقاضــي احلكــم برؤيــة خــط الشــاهد‬\n                                                                ‫احتياطــا للحكــم‪.‬‬\n\n\n\n\n       ‫أقــام املدعــي العــام دعــواه ضــد املدعــى عليــه طالب ـ ًا احلكــم بإثبــات‬\n       ‫اجتــاره يف احلبــوب املخــدرة احملظــورة وســجنه وجلــده وتغرميــه لقــاء‬\n       ‫مانســب إليه‪،‬وقــد أنكــر املدعــى عليــه هــذه التهمــة وطلبــت احملكمــة‬\n       ‫مــن املدعــي العــام البينــة علــى دعــواه فطلــب إمهالــه إلحضــار الشــهود‬\n       ‫علــى الواقعــة ونظــر ًا لتأجيــل القضيــة أكثــر مــن مــرة وعــدم إقامــة البينة‬\n       ‫فقــد قــررت احملكمــة بعــد اإلطالع على أوراق القضية ولكون الشــبهة‬\n       ‫ال تتوجــه علــى املدعــى عليــه وألن الشــهادة يجــب أن تــؤدى مشــافهة‬\n       ‫يف مجلــس احلكــم فقــد قــررت احملكمــة صــرف النظــر عــن دعــوى‬\n\n‫‪255‬‬\n\f‫املدعــي العــام وأخلــت ســبيل املدعــى عليــه وقــد اعتــرض املدعــي العــام‬\n‫علــى احلكــم وجــرى تصديــق احلكــم مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫هــذا اليــوم األحــد املوافــق ‪1434/1/18‬هـ ـ الســاعة التاســعة صباح ـ ًا‬\n‫لــدي أنــا ‪................‬القاضــي يف احملكمــة اجلزائيــة بتبــوك فتحــت‬\n‫ـاء علــى املعاملــة الــواردة لــي مــن هيئةالتحقيــق واإلدعــاء‬    ‫اجللســة بنـ ً‬\n‫العــام برقــم ‪................‬وتاريــخ ‪1433/10/16‬ه ـ واحملالــة لــي بشــرح‬\n‫فضيلــة الرئيــس رقــم ‪................‬وتاريــخ ‪1433/10/17‬هـ ـ وفيهــا حضــر‬\n‫املدعــي العــام ‪ ................‬واملعمــد مــن مرجعــه مبوجــب اخلطــاب رقــم‬\n‫ا يف تقريــر دعــواه بصفتــي مدعي ـ ًا‬      ‫‪................‬يف ‪1433/9/5‬ه ـ قائ ـ ً‬\n‫عام ـ ًا بدائــرة اإلدعــاء لفــرع الهيئــة مبنطقــة تبــوك أدعــي علــى‪/‬‬\n‫‪ ،................‬ســعودي مبوجــب الســجل املدنــي رقــم (‪ )................‬فقــد‬\n‫ورد مبحضــر الشــراء والقبــض والتفتيــش املعــد مــن قبــل الفرقــة‬\n‫القابضةمبكافحــة املخــدرات أنــه بتاريــخ ‪1433/10/22‬ه ـ توفــرت‬\n‫معلومــات لــدى مكافحــة املخــدرات مــن أحــد املصــادر الســرية تفيــد‬\n‫عــن وجودشــخص يدعى‪................/‬يســكن باالســتراحات الواقعــة‬\n‫بطريــق ‪ .....‬وميتهــن ترويــج احلبــوب احملظــورة ويقــوم بالتنســيق على جواله‬\n‫رقــم (‪ )................‬واســتعد املصــدر بالتنســيق والشــراء منــه برفقــة أحــد‬\n‫منســوبي مكافحــة املخــدرات وبالفعــل اتصــل املصــدر الســري علــى‬\n‫املــروج وطلــب منــه كميــة مــن احلبــوب احملظــورة مببلــغ وقــدره (‪)200‬‬\n‫مائتــي ريــال وطلــب منــه املــروج احلضــور إليــه عنــد محطــة ‪.........‬الواقعــة‬\n\n                                                                                       ‫‪256‬‬\n\f      ‫بجــوار ‪ .........‬لتســليمه املبلــغ ويكــون تســليم احلبــوب احملظــورة بطريــق‬\n      ‫االســتراحات الواقعةعلــى ‪.........‬وكان ذلــك علــى أمــام مــرأى ومســمع‬\n      ‫مــن الفرقــة القابضــة وبعدهــا انتقــل املصــدر برفقــة احــد أفــراد الفرقــة‬\n      ‫القابضــة ومت مقابلــة املــروج ومت تســليمه املبلــغ احلكومــي املرقــم وقــدره‬\n      ‫(‪ )200‬مائتــي ريــال علــى فئتــن حتمــل األولــى رقــم (‪ ).........‬والثانيــة‬\n      ‫(‪ ).........‬علــى مــرأى مــن الفــرد املرافــق وعندهــا طلــب املــروج مــن املصدر‬\n      ‫التوجــه إلــى طريــق االســتراحات لتســليمه احلبــوب احملظــورة وبعدهــا‬\n      ‫بثلــث ســاعة تقريبـ ًا مت مقابلــة املــروج باملــكان املتفــق عليــه وقــام املــروج‬\n      ‫بتســليم املصــدر عــدد (‪ )8‬ثمــان حبــات يشــتبه أن تكــون محظــورة علــى‬\n      ‫مــرأى مــن الفــرد املرافــق ولــم يتــم القبــض عليــه حينهــا لعــدم كشــف‬\n      ‫املصــدر وبتاريــخ ‪1433/11/20‬ه ومبراقبــة إحــدى االســتراحات الواقعــة‬\n      ‫علــى طريــق ‪.........‬شــوهد املــروج املطلــوب فتــم القبــض عليــه واتضــح أنــه‬\n      ‫املدعــى عليــه املذكــور أعــاه وبتفتيشــه شــخصي ًا لــم يعثــر معــه علــى‬\n      ‫شــيء ممنــوع وبتفتيــش االســتراحة التــي يســكن بهــا لــم يعثــر بهــا‬\n      ‫علــى ممنوعــات ولــم يعثــر معــه علــى اجلــوال الــذي مت التنســيق عليــه‬\n      ‫وباســتجواب املدعــى عليــه‪ ،................ /‬أنكــر مــا نســب إليــه جملــة‬\n      ‫وتفصيــا وأقــر بــأن الهاتــف الــذي مت التنســيق عليــه يف عمليــة الترويــج‬\n      ‫وهــو الرقــم (‪ )................‬يعــود لــه وقــد ورد محضــر تعــرف الفــرد املرافــق‬\n      ‫للمصــدر املتضمــن بعــرض املدعــى عليــه علــى الفــرد املرافــق للمصــدر‬\n      ‫الــذي شــاهد عمليــة االســتالم والتســليم فقــد تعــرف عليــه تعرف ـ ًا تام ـ ًا‬\n      ‫نافي ـ ًا للجهالة‪.‬وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪).........‬‬\n      ‫لعام‪1433‬ه ـ الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة‬\n      ‫الشــرعية بصحــة ‪ ....‬إيجابيــة عينــة احلبــوب لالمفيتامــن املنبــه للجهــاز‬\n\n\n‫‪257‬‬\n\f‫العصبــي ‪ ،‬وهــو مــن املؤثــرات العقليــة اخلاضعــة للرقابــة واملنــوه عنــه‬\n‫باجلــدول الثانــي فئــة (ب) يف تعميــم صاحــب الســمو امللكــي وزيــر‬\n‫الداخليــة رقــم (‪ )89400/19‬وتاريــخ ‪1426/10/25‬ه ـ وقــد أســفر‬\n‫التحقيــق عــن توجيــه االتهــام للمدعــى عليــه ‪ ،................ /‬بترويــج عــدد‬\n‫(‪ )8‬ثمــان حبــات مــن احلبــوب التــي حتتــوى علــى مــادة االمفيتامــن املنبــه‬\n‫للجهــاز العصبــي احملظــور عــن طريــق البيــع وذلــك لألدلــة والقرائــن‬\n‫التاليــة ‪ -1 :‬محضــر التنســيق والشــراء والقبــض ـ املنــوه عنــه ـ واملــدون‬\n‫علــى الصفحــات رقــم (‪ )13-12-4-2‬مــن دفتــر االســتدالل املرفــق لفــة‬\n‫رقــم (‪ -2.)1‬إقــرار املتهــم بــأن الهاتــف التــي مت التنســيق عليــه يف عمليــة‬\n‫الترويــج عائــد ًا لــه واملرفــق لفــة رقــم (‪ -3.)14‬محضــر تعــرف الفــرد‬\n‫املرافــق ـ املنــوه عنــه ـ واملرفــق لفةرقــم (‪-4.)20‬التقريــر الكيميائــي‬\n‫الشــرعي ـ املنــوه عنــه ـ واملرفــق لفــة رقــم (‪ . )22‬وحيــث إن مــا أقــدم‬\n‫عليــه املدعــى عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا ومجــرم‬\n‫ومعاقــب عليــه نظام ـ ًا اســتناد ًا للمــادة (الثالثــة) الفقــرة (الثانيــة) مــن‬\n‫نظــام مكافحةاملخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n‫رقــم ( م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب مــا يلــي ‪ /1:‬إثبــات مــا‬\n‫أســند إليــه‪ /2 .‬احلكــم عليــه بالســجن واجللــد والغرامــة لقــاء مــا أســند‬\n                                         ‫إليــه‪ ،‬اســتناد ًا للفقــرة (‪ )1‬مــن املــادة‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الســبت املوافــق ‪1434/1/24‬ه ـ‬\n‫الســاعة احلاديــة عشــرة والنصــف صباح ـ ًا فتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي العــام واملدعــى عليــه ووكيلــه املثبــت حضــوره واســمه يف اجللســة‬\n‫الســابقة ‪ ،‬وبســؤال املدعــي العــام عــن بينتــه التــي وعــد بإحضارهــا‬\n‫أجــاب بقولــه لقــد أخبــرت الشــهود باجللســة إال أنهــم لــم يحضــروا وأطلــب‬\n\n\n                                                                                           ‫‪258‬‬\n\f      ‫إمهالــي ألجــل إحضارهــم مــرة أخــرى وحيــث ال مانــع فقــد جــرى رفــع‬\n      ‫اجللســة حلــن ذلــك ‪ ،‬وحــددت موعــد ًا جديــد ًا لســماع البينــة وذلــك يف‬\n      ‫يــوم األربعــاء القــادم املوافــق ‪1434/1/28‬ه ـ الســاعة العاشــرة صباحـاً‪،‬‬\n      ‫وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى ســيدنا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم وحــرر يف الســاعة احلاديــة عشــرة والنصــف مــن ضحــى‬\n                                                ‫يــوم الســبت املوافــق ‪1434/1/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء املوافــق ‪1434/1/28‬ه ـ‬\n      ‫الســاعة احلاديــة عشــرة صباح ـ ًا فتحــت اجللســة وفيهــا حضــر املدعــي‬\n      ‫العــام واملدعــى عليــه ووكيلــه املثبــت حضــوره واســمه يف اجللســة‬\n      ‫الســابقة‪ ،‬وبســؤال املدعــي العــام عــن بينتــه التــي وعــد بإحضارهــا‬\n      ‫أجــاب بقولــه لقــد أخبــرت الشــهود باجللســة إال أنهــم لــم يحضــروا وأطلــب‬\n      ‫إمهالــي ألجــل إحضارهــم مرةأخــرى وحيــث ال مانــع فقــد جــرى رفــع‬\n      ‫اجللســة حلــن ذلــك ‪ ،‬وحــددت موعــد ًا جديــد ًا لســماع البينــة وذلــك يف يــوم‬\n      ‫األحــد القــادم املوافــق ‪1434/2/3‬ه ـ الســاعة العاشــرة صباحـ ًا ‪ ،‬كمــا‬\n      ‫أفهمــت املدعــي العــام أن املوعــد القــادم ســيكون املهلــة األخيــرة ألجــل‬\n      ‫إحضــار بينتــه ‪ ،‬وإال فســأعده عاجــز ًا عــن إحضارهــا فتفهــم ذلــك‪،‬‬\n      ‫وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى ســيدنا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم وحــرر يف الســاعة احلاديــة عشــرة مــن ضحــى يــوم األربعــاء‬\n                                                              ‫املوافــق ‪1434/1/28‬ه ـ‬\n      ‫ثــم يف جلســة أخــرى وفيهــا حضــر املدعــي العــام واملدعــى عليــه ووكيلــه‬\n      ‫املثبــت حضــوره واســمه يف اجللســة الســابقة ‪ ،‬وبســؤال املدعــي العــام‬\n      ‫عــن رقــم اجلــوال الــذي ذكــر يف الدعــوى أنــه مت التنســيق مــن خاللــه‬\n      ‫وهــو (‪ )................‬هــل أقــر املدعــى عليــه أنــه عائــد لــه ؟ فأجــاب بقولــه‬\n\n\n‫‪259‬‬\n\f‫نعــم كمــا يف اللفــة (‪ )14‬مــن املعاملــة هكــذا أجــاب املدعــي العــام‬\n‫‪،‬وبالرجــوع إلــى اللفــة(‪ )14‬وجــدت أن املدعــى عليــه لــم يقــر صراحــة‬\n‫بــأن الرقــم يعــود لــه بــل قــال إنــه مــع أخــي يف ‪ ، .....‬وهــو باســمه هكــذا‬\n‫أجــاب املدعــى عليــه ‪ ،‬ويف هــذه اجللســة طلــب وكيــل املدعــى عليــه‬\n‫إضافــة بعــض النقــاط املتعلقــة بالقضيــة ونصهــا كمــا يلــي ‪( :‬أتقــدم‬\n‫لفضيلتكــم مبذكــرة جوابيــة علــى دعــوى املدعــي العــام وبصفتــي‬\n‫ا عــن املتهــم ‪................‬داللــة املــادة (‪ )173‬مــن نظــام اإلجــراءات‬‫وكي ـ ً‬\n‫اجلزائيــة التــي تنــص علــى ( لــكل مــن اخلصــوم أن يقــدم إلــى احملكمــة‬\n‫مــا لديــه ممــا يتعلــق بالقضيــة مكتوب ـ ًا ليضــم إلــى ملــف القضيــة ) ‪،‬‬\n‫واســتهل مبــا اســتهل اهلل بــه بقولــه تعالــى ( ربنــا افتــح بيننــا وبــن قومنــا‬\n‫باحلــق وأنــت خيــر الفاحتــن ) ويبــدو وجــود التباســات يف الدعــوى ويف‬\n‫مفاهيــم القضيــة وقبــل أن أشــير إلــى موطــن االلتبــاس أوضــح حقيقــة‬\n‫القضيــة ولعــل مــن شــرح القضيــة مــا يزيــل الغمــوض واحلكمــة ضالــة‬\n‫املؤمــن ‪ ،‬وذي بــدء أؤكــد لعدالــة ناظــر القضيــة _ أحســن اهلل إليــه _‬\n‫حرصــي التــام علــى توضيــح احلقائــق والوقائــع ومــا تــدل عليــه القواعــد‬\n‫األصوليــة الراســخة املتعلقــة بهــذه الدعــوى ونحــن علــى يقــن مــن الرؤيــة‬\n‫حتريكــم للعــدل وانحيازكــم لــه ‪-:‬‬   ‫َّ‬      ‫الثاقبــة لفضيلتكــم وواثقــن مــن‬\n‫أوالً‪ -:‬أن دعــوى املدعــى العــام متناقضــة مــع البينــة املقدمــة مــن موكلــي‬\n‫واملتمثلــة بعــدة نقــاط أال وهــي ‪ _1 -:‬ال حيــازة تذكــر أثنــاء القبــض‬\n‫علــى موكلــي ممــا ينفــي عنــه ركــن التلبــس بهــذه اجلرميــة ‪ _2.‬ال حيــازة‬\n‫محــرزة يف منزلــه ممــا ينســف معــه االدعــاء عــن كونــه ميتهــن الترويــج‬\n‫وكان غــرض إدارة مكافحــة املخــدرات تهويالملوقــف أمــام فضيلــة‬\n‫ناظــر القضيــة وخلــق ضبابــة تخيــم علــى فطنــة فضيلتكــم فأصبــح‬\n\n\n                                                                                         ‫‪260‬‬\n\f      ‫االدعاءأشــبه بحياكــة ثــوب مهلهــل ملــيء بالترقيعــات فــاهلل املســتعان‬\n      ‫عمــا يصفــون ‪ -3.‬عــدم ورود اتصــاالت مــن موكلــي تفيــد التنســيق‬\n      ‫قبــل واقعــة القبــض عليــه أو اإلشــارة إلــى الكميــة املدعــى بهــا ‪-4.‬أن‬\n      ‫موكلــي لــم يســلم مبحضــر الضبــط ولــم يقــر بــه حيــث أنــه لــم يشــاهد‬\n          ‫الكميــة املدعــى ضبطهــا ولــم يعلــم عنهــا إال بعــد أن مت اتهامــه بهــا‪.‬‬\n      ‫‪ -5‬عــدم التحديــد الدقيــق ســواء الزمانــي أو املــكان لتســليم احلبــوب‬\n      ‫املزعومــة حيــث ذكــر علــى طريــق االســتراحات مــع مالحظــة االمتــداد‬\n      ‫الكبيــر لطريــق االســتراحة دون حتديــد لهــذه االســتراحة‪-6 .‬لقــد خلت‬\n      ‫أدلــة املدعــي العــام مــن ذكــر برنــت اتصــال ومحضــر تفريــغ مكاملــات‬\n      ‫فــا يتصــور أن يكــون هنــاك تســلم وتســليم دون تفــاوض علــى مبلــغ‬\n      ‫وكميــة ‪-7.‬أن موكلــي لــم يقــر مبحضــر التعــرف حيــث إنــه وقــع بعــد‬\n      ‫القبــض عليــه ‪-8 .‬ممــا يؤكــد أن البينــة الــواردة يف الدعــوى لــم تكــن‬\n      ‫موصلــه لالتهــام قولهــم « علــى مســمع مــن الفرقــة » فهــذا املســمع كمــا‬\n      ‫مت وصــف املدعــى العــام هــو عــن طريــق هاتــف وصــوت موكلــي للفرقــة‬\n      ‫غيــر معــروف للداللــة علــى أنــه هــو الفاعــل مبــا مت بالهاتــف ‪ ،‬والهاتــف‬\n      ‫ال ميكــن أن ُتبنــى األحــكام علــى مــا مت بــه كونــه ممكــن التالعــب‬\n      ‫بــه وممكــن أن يســتخدم مــن غيــر صاحبــه ومــا مت ذكــره أعــاه يتفــق‬\n      ‫مــع األصــول الشــرعية أن احلــدود تــدرأ بالشــبهات لقولــه صلــى اهلل‬\n      ‫عليــه وســلم ((ادرؤوا احلدودبالشــبهات)) وذلــك أن احلــدود مبنيــة علــى‬\n      ‫الســتر والــدرء بالشــبهات أولــى مــن الشــهادة عليــه واحلــال كمــا ذكــر‬\n      ‫فيتضــح لعــدل فضيلتكــم ممــا ســبق ذكــره تناقــض دعــوى املدعــى‬\n      ‫العــام مــع الدفــوع املقدمــة واســتنتاجات واســتنباطات الئحــة االتهــام ‪،‬‬\n      ‫فكيــف يكــون االتهــام ويســتقيم مــع جــل هــذه التناقضــات فمــا ثبــت‬\n\n\n‫‪261‬‬\n\f‫بيقــن ال يرتفــع إال بيقــن ‪ ،‬وممــا هــو معلــوم لفضيلتكــم أن التناقــض‬\n‫يـ ُـرد الدعــوى ويجعلهــا علــى األصــل وهــو البــراءة ألن دعــوى املدعــي‬\n‫العــام قائمــة علــى الظــن والتكهنــات وال يخفــى علــى فضيلتكــم أنــه‬\n‫يشــترط يف البينــة أن تكــون موصلــة ويف الدليــل أن يكــون قطعيــا‬\n‫ألنــه يفيــد اليقــن وال عبــرة بالدليــل الظنــي الــذي يفيــد التوهــم ومــا‬\n‫ذكــره املدعــي العــام هــو ظــن ســيء مــن حيــث اتهامــه بالترويــج دون‬\n‫ا ‪.‬ثانيـاً‪-:‬‬‫توفــر أركانــه ودون الوقــوف علــى نفــي للتهمــة جملــة وتفصيـ ً‬\n‫أن موكلــي يدفــع بعــدم صحــة مــا ورد مــن حيــث ملكيتــه للرقــم املشــار‬\n‫إليــه بالدعــوى ( ‪ )................‬حيــث أن موكلــي يريــد الفــكاك مــن هــذه‬\n‫البينــة ‪ ،‬بــل هــي احلقيقــة التــي تعضدهــا حقيقــة أن هــذا اجلــوال قــدمي‬\n‫التســجيل وانــه مســجل باســم شــقيقه ‪ ،‬ويخشــى موكلــي أن يكــون‬\n‫مــن مســببات االتهــام وأن فضيلتــه إن ال قــدر اهلل باألخــذ بــه واعتبارهــا‬\n‫شــبه بحقــه هــي مــن بــاب التوســع بالقرائــن والتوســع بالقرائــن يــورث‬\n‫احليــف والظلــم (ملتمســن مــن فضيلتكــم حكمــة معهــودة وفقكــم‬\n‫اهلل )‪.‬ثالث ًــا‪ -:‬لقــد اعتلــى عمــل مكافحــة املخــدرات عيب ـ ًا مــن العيــوب‬\n‫اإلجرائيــة مــا يدفــع ببطالنــه ‪ ،‬وذلــك ملخالفتــه ملــا أمــر بــه ولــي األمــر‬\n‫مــن حيــث قيــد احلريــات ‪ ،‬وحيــث أن القبــض والتفتيــش حصــل دون‬\n‫حيــازة فإنــه ال يعتــد بــه ملخالفتــه املــواد‪ )33.35.40.46.47(،‬مــن‬\n‫نظــام اإلجــراءات اجلزائيــة وهــو يعتبــر قيــد ًا علــى احلريــات الشــخصية‬\n‫بوصفهــا حق ـ ًا طبيعي ـ ًا مــن حقــوق اإلنســان يســتوي يف ذلــك أن يكــون‬\n‫القيــد قبض ـ ًا أو تفتيش ـ ًا وال يجــوز إال يف حــاالت التلبــس أو بــإذن مــن‬\n‫احلاكــم اإلداري ‪ ،‬وهاتــن احلالتــن غيــر متوفــرة يف هــذه القضيــة‬\n‫‪.‬مخالفــن بذلــك إجــراءات التفتيــش الصــادرة باملرســوم امللكــي رقــم‬\n\n\n                                                                                       ‫‪262‬‬\n\f      ‫م‪39/‬وتاريــخ ‪1422/7/28‬ه ـ الفصــل الرابــع املــواد (‪ (46،40‬رابع ـاً‪-:‬‬\n      ‫عدالــة املصــدر محــل للتشــكيك بهــا ‪ ،‬فمــن املعلــوم يقينـ ًا لفضيلتكــم‬\n      ‫بــأن املصــادر الســرية التــي تســتعني بهــا إدارة املخــدرات وعــدم صحــة‬\n      ‫الروايــة املذكــورة مبــدأ قيــام القضــاء علــى احلجــة والبرهــان الســيما‬\n      ‫أن اإلثبــات يف القضــاء الشــرعي هــو املعيــار يف متييــز احلــق مــن الباطــل‬\n      ‫‪ ،‬والغــث مــن الســمني واحلاجــز أمــام األقــوال الكاذبــة والدعــوى‬\n      ‫الباطلــة وعلــى هــذا ‪ ،‬فــكل ادعــاء يبقــى يف نظــر القضــاء الشــرعي‬\n      ‫محتاج ـ ًا إلــى دليــل وال يؤخــذ بــه إال باحلجــة والبرهــان ‪ ،‬يقــول جــل‬\n      ‫ن [ ويقــول ســبحانه]‬      ‫ك ْن ُتـ ْـم َصادِقِ ـ َ‬\n                                                        ‫َكـ ْـم ِإنْ ُ‬      ‫وعــا ‪ { :‬قُ ـ ْـل َها ُتــوا ُب ْر َهان ُ‬\n      ‫ـون } ‪.‬كمــا أن‬   ‫كاذ ُِبـ َ‬                ‫الش ـ َه َدا ِء َف ُأو َل ِئـ َـك عِ ْنـ َـد َّ ِ‬\n                                   ‫الل ُهـ ُـم ا ْل َ‬                                           ‫َف ـ ِإ ْذ َلـ ْـم َي ْأ ُتــوا ِب ُّ‬\n      ‫أوليــاء األمــر وضعــوا ضمانــات للمتهــم ففــي البــاب التاســع مــن نظــام‬\n      ‫املرافعــات الشــرعية التــي تتحــدث عــن اإلجــراءات الشــرعية لإلثبــات‬\n      ‫تبــرز يف املــواد اآلتيــة ‪-1 :‬جــاء يف املــادة الســابعة والتســعني مــا نصــه ‪:‬‬\n      ‫(يجــب أن تكــون الوقائــع املــراد إثباتهــا أثنــاء املرافعــة متعلقــة بالدعــوى‬\n      ‫منتجــة فيهــا جائــز ًا قبولهــا )‪-2‬نصــت املــادة السادســة واخلمســون بعــد‬\n      ‫املائــة علــى مــا يلــي ‪ ( :‬لــكل مــن اخلصــوم أن يثبــت مــا يخالــف القرينــة‬\n      ‫التــي اســتنتجها القاضــي وحينئــذ تفقــد القرينــة قيمتهــا يف اإلثبــات )‬\n      ‫ســابعاً‪ -:‬لــم يتــم الذكــر مــن املدعــي العــام عــن مصيــر املبلــغ املرقــم‬\n      ‫املزعــوم وعــن وجــوده مــن عدمــه مــع موكلــي ممــا يكــذب الزعــم يف‬\n      ‫الدعــوى ‪.‬ثامن ـاً‪ -:‬أن محضــر التنســيق املزعــوم يعتليــه الباطــل مــن بــن‬\n      ‫يديــه فيتضــح لفضيلتكــم عنــد مراجعتــه ‪ ،‬أن اإلشــهاد الــوارد فيــه‬\n      ‫إشــهاد غيــر مباشــرة فيكــون أقــل قيمــة مــن الشــهادة العينيــة التــي تقــع‬\n      ‫مــن حاســة الشــاهد مباشــرة علــى الواقعــة وتعلمــون فضيلتكــم ونحــن‬\n\n\n‫‪263‬‬\n\f‫نتعلــم مــن فضيلتكــم أن واقعــة الشــهادة ذات أهميــة قانونيــة وتكســب‬\n‫هــذه األهميــة مــن وقــوع اجلرميــة ونســبتها إلــى املتهــم فيجــب أن تكــون‬\n‫الشــهادة يقينيــة إعمــاال بحديــث النبــي الكــرمي صلــى اهلل عليــه وســلم‬\n‫(( علــى مثلهــا فاشــهد أو دع ))كمــا أن الشــهادة الــواردة يف احملاضــر‬\n‫يعتليهــا مخالفتهــا الشــتراطات الشــهادة وذلــك لألمورالتاليــة ‪-1 -:‬أن‬\n‫اإلشــهاد الــوارد يف احملاضــر إشــهاد مــن رجــل واحــد وبذلــك لــم يكمــل‬\n‫نصــاب الشــهادة لقــول ابــن عاصــم ((ويكتفــى بهــا بعدلــن )) اســتدالال‬\n‫بقولــه تعالــى (واشــهدوا ذوي عــدل منكــم) وقولــه تعالــى (واستشــهدوا‬\n‫شــهيدين مــن رجالكــم ) وال صحــة للقــول القائــل بصحــة قبــول البينــة‬\n‫بشــاهد واحــد فقــط دون النظــر إلــى ميــن املدعــى عليــه ألن النبــي ‪-‬‬\n‫صلــى اهلل عليــه وســلم ‪ -‬قضــى بشــهادة شــاهد واحــد وميــن صاحــب احلق‬\n‫وقالــوا أن اإلثبــات بالشــاهد واليمــن إمنــا يقبــل يف األمــوال دون احلــدود‬\n‫والقصــاص‪-2‬أن الشــهادة قاصــرة حيــث لــم تصــرح بحقيقــة االســتالم‬\n‫والتســليم وصف ـ ًا نافي ـ ًا للجهالــة واســتحالة وقــوع وتصــور الشــهادة‬\n‫لكــون أن موكلــي علــى حــد روايــة املكافحــة قــام بالتســليم بطريــق‬\n‫االســتراحات فكيــف يتســن للشــاهد مالحظــة وتقريــر كنــه احلبــوب‬\n‫مــن عدمــه خصوصــا أن املنطقــة مظلمــة واملدعــى بــه مت بليــل ‪ ،‬لــكل‬\n‫مــا ســبق ومــا أثيــر مــن نقــاط وجيهــه ‪ ،،‬فإننــي ألتمــس مــن عدالتكــم‬\n‫وإحقاقـ ًا للحــق وحتــى تبــرأ الــذمم أمــام اهلل أو ًال ثــم أمــام بــارئ األكــوان‬\n‫األمــر بالعــدل يف محكــم تنزيلــه احلكــم بإطــاق ســراح موكلــي فــورا‬\n‫واحلكــم بتبرئتــه مــن االتهــام وإلغــاء تبعــات هــذه الدعــوى التــي صــادرت‬\n‫حرياتــه وطاقاتــه وســمعته والن هنــاك فــرق كبيــر بني الشــك والقرينة‪،‬‬\n                                             ‫فالقرينــة هــي اســتنتاج علــى ســبيل‬\n\n\n                                                                                          ‫‪264‬‬\n\f      ‫اجلــزم واليقــن وميكــن أن تســتند إليهــا اإلدانــة أمــا الشــك فهــو اســتنتاج‬\n      ‫على سبيل اإلمكان وال تبنى عليه اإلدانة ‪ ،‬ألنها ليست دليال ويجانب‬\n      ‫القاضــي الصــواب إذا أســتعملها كدليــل ألن الشــك يف قيمــة القرينــة‬\n      ‫يفســر ملصلحــة املتهــم (مثــل كامــل األدلــة) ‪ ،‬أمــا الشــك املتدحــرج‬\n      ‫يفســر ضــد مصلحــة املتهــم (وال تبنــى عليهــا األدلــة يف وصــف فعــل لــم‬\n      ‫يكــن لــه أصــل فأصبحــت البينــة غيــر موصلــه ملــا يدعيــه املدعــى العــام‬\n      ‫بحقــه وموكلــي يســتصرخكم إعمــال املصلحــة والعمــل بســد الذرائــع‬\n      ‫وزيــادة االجتهــاد املقاصــدي يف احلكــم وإعمــال املصلحــة وســد الذرائــع‬\n      ‫وزيــادة االجتهــاد املقاصــدي يكــون مــن فضيلتكــم بتغليــب النظــرة‬\n      ‫الســوية ملوكلــي وحســن الظــن بــه واملوازنــة بــن ســيرته املاضيــة وخلوهــا‬\n      ‫ممــا يقــدح بهــا ‪ ،‬ولنــا يف الســلف الصالــح خيــر قــدوة حيــث كانــت‬\n      ‫أساســا يف اجتهــادات عمــر رضــي اهلل عنــه فيمــا اليخالــف‬    ‫ً‬     ‫املصلحــة‬\n      ‫نصــا‪ ،‬فــإذا كان يف الواقعــة نــص خــاص التــزم بــه عمــر‪ ،‬علــى نحــو‬      ‫ً‬\n      ‫يحقــق املصلحة‪،‬وقــد متيــز عمــل عمــر ‪-‬رضــي اهلل عنــه‪ -‬باملصلحــة أنــه‬\n      ‫ضبطهــا بضوابطهــا التــي ال تصطــدم فيهــا مــع النصــوص أو األقيســة‬\n      ‫الصحيحــة‪ ،‬كمــا أعمــل بوضــوح فقــه املوازنــات بــن املصالح‪،‬واختيــار‬\n      ‫األكثــر نفعــا ‪ ،‬وإذا كان البــد لتحقيــق املصلحــة مــن حــدوث مفســدة‬\n      ‫فــكان يرتكــب املفســدة األخــف ليدفــع بهــا املفســدة األعظم فمفســدة‬\n      ‫زج موكلــي بالســجن وبعــده عــن ذويــه ألعظــم مفســدة وفقدانــه ملــا‬\n      ‫يتقــوت بــه لــه الضــرر املنهــي عنــه واملصيبــة اجللــل ‪،‬وكان ‪-‬رضــي اهلل‬\n      ‫عنــه‪ -‬خيــر مــن يعمــل بســد الذرائــع وكــذا بفتحهــا ‪ ،‬وخيــر مــن ينظــر‬\n      ‫إلــى املــآالت ومــا ينتــج عنهــا ‪،‬فأســس بذلــك لفقــه رشــيد يف التطبيــق‬\n      ‫املتــوازن لســد الذرائــع‪ ،‬والنظــر إلــى املــآالت‪ ،‬فــا هــو يهملهــا غاضــا‬\n\n\n‫‪265‬‬\n\f‫النظــر عمــا يترتــب عليهــا يف املســتقبل‪ ،‬وال هــو يطلقلهــا العنــان يف‬\n‫ضيقــا بذلــك الواســع علــى املســلمني‪ ،‬وأنتــم فضيلتكــم‬          ‫التطبيــق ُم ِّ‬\n‫خيرخلــف خليــر ســلف ) هكــذا أضــاف مــوكل املدعــى عليــه ‪،‬‬\n‫وبعــرض مــا أضافــه املدعــى عليــه علــى املدعــي العــام أجــاب بقولــه ‪:‬‬\n‫الصحيــح مــا ذكرتــه وبســؤاله عــن بينتــه التــي وعــد بإحضارهــا أجــاب‬\n‫بقولــه لــم أمتكــن مــن إحضــار بينتــي ‪ ،‬وأقــرر االكتفــاء مبــا جــاء يف‬\n‫ـاء‬\n‫طيــات املعاملــة مــن أدلــة وقرائــن هكــذا أجــاب املدعــي العــام ‪ ،‬فبنـ ً‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابةونظــر ًا إلنــكار املدعــى عليــه أن‬\n‫اجلــوال املضبــوط معــه وقــت القبــض عائــد إليــه ‪ ،‬وألنــه أنكــر مــا ُنســب‬\n‫إليــه مــن قيامــه بالترويــج‪ ،‬وألن املبلــغ املرقــم لــم يوجــد مــع املدعــى عليــه‬\n‫حــن القبــض ‪ ،‬وألنــه لــم يعثــر معــه علــى اجلــوال املذكــور يف الدعــوى‬\n‫حــن القبــض عليــه ‪ ،‬بــل إنــه لــم يثبــت لــدي أن اجلــوال املذكــور بعاليــه‬\n‫يخــص املدعــى عليــه حيــث أنكــره املدعــى عليــه وال بينــة للمدعــي العــام‬\n‫يف متلــك املدعــى عليــه للرقــم املذكــور ‪ ،‬ونظــر ًا لعجــز املدعــى العــام‬\n‫عــن إحضــار بينتــه وال بينــة ســواها ونظــر ًا لكــون الشــبهة ال تتوجــه علــى‬\n‫املدعــى عليــه مبــا نســبه لــه املدعــي العــام وألن الشــهادة ال بــد أن تــؤدى‬\n‫مشــافهة يف مجلــس احلكــم ملــا نــص عليــه الفقهــاء ومــن ذلــك قولهــم‬\n‫(وال يجــوز للقاضــي احلكــم برؤيــة خــط الشــاهد احتياط ـ ًا للحكــم )‬\n‫انظــر كشــاف القنــاع (‪ )337/4‬وقــد نــص نظــام املرافعــات الشــرعية‬\n‫مــاده (‪ )120‬علــى أنــه ال يجــوز االســتعانة يف أداء الشــهادة مبذكــرات‬\n‫مكتوبــة بــل يجــب أن تــؤدى شــفوي ًا كمــا نــص نظــام اإلجــراءات‬\n‫اجلزائيــة علــى أن الشــهادة ال بــد أن تــؤدى يف مجلــس القضــاء كمــا‬\n‫ا‬‫يف املــادة (‪ )169‬ونظــر ًا ألن تخلــف الشــاهد عــن احلضــور يعتبــر دلي ـ ً‬\n\n\n                                                                                          ‫‪266‬‬\n\f      ‫علــى تراجعــه عــن الشــهادة ومعلــوم أن الشــاهد يف حقــوق اهلل تعالــى ال‬\n      ‫يلــزم باحلضــور وألن الشــاهد واحلالــة هــذه يعتبــر مجهــول احلــال ‪ ،‬وألنــه‬\n      ‫قــد مت إمهــال املدعــي العــام ثــاث مــرات ألجــل إحضــار بينتــه إال أنــه‬\n      ‫لــم يحضرهــا ‪ ،‬لذلــك كلــه فقــد قــررت صــرف النظــر عــن دعــوى‬\n      ‫املدعــي العــام لعــدم ثبوتهــا لدي‪،‬وأخليــت ســبيل املدعــى عليــه مــن هــذه‬\n      ‫الدعــوى ‪ ،‬هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض احلكــم علــى املدعى‬\n      ‫عليــه قنــع بــه ‪ ،‬أمــا املدعــي العــام فقــرر اعتراضــه علــى احلكــم بالئحــة‬\n      ‫فأجبتــه إلــى طلبــه وأفهمتــه بتعليمــات االســتئناف حيــال ذلــك ثــم جــرى‬\n      ‫تســليمه نســخة مــن القــرار ليبــدأ ميعــاد االعتــراض مــن تاريــخ احلكــم‪،‬‬\n      ‫وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه أجمعــن حــرر يف الســاعة الثانيــة عشــرة مــن ضحــى يــوم األحــد‬\n                                                                 ‫املوافــق ‪1434/2/3‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلزائيــة األولى‬\n      ‫لتدقيــق القضايــا اجلزائيــة يف محكمــة االســتئناف مبنطقــة تبــوك علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك برقــم‬\n      ‫‪ ..........‬وتاريــخ ‪1434/3/4‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪.......... /‬رقــم ‪..........‬وتاريــخ ‪1434/2/3‬ه ـ اخلــاص بدعوى املدعي‬\n      ‫العــام ضــد‪.......... /‬يف قضيــة مخــدرات علــى النحــو املوضــح يف القــرار‬\n      ‫واملتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة والالئحــة االعتراضيــة قررنــا‬\n      ‫املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى إرفــاق صــورة مصدقــة‬\n      ‫مــن الوكالــة باملعاملــة وكذلــك لــم يلحــق يف ضبطــه إطالعــه علــى‬\n      ‫الالئحــة االعتراضيــة للتنبيــه لذلــك مســتقبالً‪.‬واهلل واملوفــق وصلــى اهلل‬\n                                    ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫‪267‬‬\n\f268\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":255,"source_page_end":268,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"70e60bc0ecdf5f3c925dccc4b9292abee29ac6f17371d8350caa9a3f56fa831d","normalized_text_hash":"a36197511b733245c473c57a3ddf9df6b3ede7130549c8ab0ba8a41434f4653a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p255-34341462"},{"id":"6dd41b1a-3f60-5db7-b97d-37a27290d67a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -حيازة احلشيش املخدر - تعاطي احلشيش املخدر -عدم وجود سوابق -إقرار املدعى عليه -تعزير بالسجن واجللد والغرامة املالية ومصادرة اجلوال واملنع","document_number":"33444872","case_number":"33611360","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/02","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -حيازة احلشيش املخدر - تعاطي احلشيش املخدر -عدم وجود سوابق -إقرار املدعى عليه -تعزير بالسجن واجللد والغرامة املالية ومصادرة اجلوال واملنع","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33444872:‬تاريخه ‪1433/11/02 :‬هـ‬\n                          ‫رقم الدعوى ‪33611360:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                   ‫‪ 346635‬تاريخه‪1434/01/10 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬حيــازة احلشــيش املخــدر ‪-‬‬\n       ‫تعاطــي احلشــيش املخــدر ‪ -‬عــدم وجــود ســوابق ‪ -‬إقــرار املدعــى عليــه‬\n       ‫‪ -‬تعزيــر بالســجن واجللــد والغرامــة املاليــة ومصــادرة اجلــوال واملنــع‬\n                                                                      ‫مــن الســفر‪.‬‬\n\n\n\n\n       ‫‪ .1‬مــا قــرره أهــل العلــم أن التعازيــر تتداخــل ‪ .‬ينظــر كشــاف القنــاع‬\n                                                                       ‫(‪.)124/6‬‬\n                 ‫‪ .2‬املادة (‪ )38‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                 ‫‪ .3‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                 ‫‪ .4‬املادة (‪ )60‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                 ‫‪ .5‬املادة (‪ )62‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n       ‫ادعــى املدعــي العــام علــى املدعــي عليــه ببيــع قطعــة مــن احلشــيش املخــدر‬\n       ‫بقصــد التعاطــي والترويــج ‪ ،‬تبلغــت اجلهــة األمنيــة بنــاء علــى مــا أفــاده‬\n       ‫أحــد املصــادر الســرية ‪ ،‬اســتعداده لشــراء احلشــيش املخــدر مــن املدعــى‬\n       ‫عليــه علــى مســمع مــن الفرقــة القابضــة ‪ ،‬ومت اإلتفــاق علــى ذلــك ‪ ،‬ومت‬\n       ‫تزويــد املصــدر باملبلــغ املرقــم ‪ ،‬وتفتيشــه وتفتيــش الســيارة ‪ ،‬وتكليــف‬\n\n‫‪269‬‬\n\f‫أحــد األفــراد مبرافقتــه ‪ ،‬فتــم االنتقــال للموقــع املتفــق عليــه ‪ ،‬وتقابــل‬\n‫املصــدر مــع املدعــى عليــه ‪ ،‬وســلم املصــدر املبلــغ املرقــم للمدعــى عليــه‪،‬‬\n‫وســلمه املدعــى عليــه قطعــة تــزن (‪ ) 4.400‬أربعــة جرامــات وأربعمائــة‬\n‫مليجــرام ‪ ،‬يشــتبه أن تكــون مــن احلشــيش املخــدر‪ ،‬ثــم عــاد املصــدر‬\n‫وســلم القطعــة للفــرد ‪ ،‬فتــم القبــض علــى املدعــى عليــه‪ ،‬وبتفتيــش‬\n‫الســيارة عثــر علــى قطعــة ســوداء يشــتبه أن تكــون مــن احلشــيش بلــغ‬\n‫وزنهــا ( ‪ ) 2.800‬جرامــن وثمامنائــة مليجــرام كمــا عثــر علــى املبلــغ‬\n‫املرقــم بالقــرب مــن (ناقــل احلركــة ) داخــل ســيارته ‪ ،‬وطلــب املدعــي‬\n‫العــام تعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة واملنــع مــن‬\n‫الســفر ومصــادرة اجلــوال و الشــريحة ‪ ،‬أقــر املدعــى عليــه ببيــع قطعــة‬\n‫مــن احلشــيش وتعاطيــه احلشــيش املخــدر‪ ،‬وأنكــر حيــازة قطعــة مــن‬\n‫احلشــيش بقصــد الترويــج وإمنــا كانــت بقصــد التعاطــي ‪ ،‬بطلــب البينــة‬\n‫مــن املدعــي العــام علــى دعــواه علــى حيــازة املدعــى عليــه القطعــة األخــرى‬\n‫ذات الــوزن (‪ )2.800‬للترويــج فلــم يســتطع إثبــات ذلــك ‪ ،‬صــدر احلكــم‬\n‫علــى املدعــى عليــه بالســجن واجللــد والغرامــة ومصــادرة هاتفــه النقــال‬\n‫واملنــع مــن الســفر ومت النــزول عــن احلــد األدنــى للعقوبــة ‪ ،‬إلبــداء املدعــى‬\n‫عليــه التوبــة والنــدم ‪ ،‬وتعهــده بعــدم العــودة ملثلــه ‪ ،‬وخللــوه ســجله مــن‬\n‫الســوابق اجلنائيــة واحلكــم بحــد املســكر بحــق املدعــى عليــه واحلكــم‬\n‫بــرد باقــي مــا جــاء يف دعــوى املدعــي العــام ‪ ،‬وقنــع املدعــى عليــه باحلكم‬\n‫‪ ،‬وقــرر املدعــي العــام اعتراضــه علــى احلكــم بالئحــة اعتراضيــة ‪،‬‬\n                                   ‫صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                        ‫‪270‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بعنيــزة‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بعنيــزة برقــم وتاريــخ ه ـ حضــر املدعــي العــام ‪ ......‬وادعــى علــى احلاضــر‬\n      ‫معــه ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ......‬قائــا يف دعــواه‬\n      ‫أدعــي علــى املدعــى عليــه املذكــور عســكري يقيــم يف محافظــة‬\n      ‫ـاء علــى مــا أبــداه أحــد املصــادر الســرية‬‫عنيــزة أوقــف بتاريــخ ه ـ وبنـ ً‬\n      ‫بعنيــزة مــن اســتعداد لشــراء حشــيش مخــدر مــن املدعــى عليــه فقــد مت‬\n      ‫متكينــه مــن االتصــال بــه علــى رقــم هاتفــه النقــال (‪ )......‬وعلــى مســمع‬\n      ‫مــن الفرقــة القابضــة طلــب منــه املصــدر حشيش ـ ًا مخــدر ًا مببلــغ (‪)200‬‬\n      ‫مائتــي ريــال فوافقــه علــى أن يتقابــا بالقــرب مــن أحــد األســواق فتــم‬\n      ‫تفتيــش املصــدر تفتيشـ ًا شــخصي ًا وتفتيــش ســيارته وترقيــم مبلــغ بالقــدر‬\n      ‫املتفــق عليــه وتســليمه لــه وتكليــف أحــد رجــال األمــن مبرافقتــه فتــم‬\n      ‫االنتقــال للموقــع املتفــق عليــه فشــوهدت ســيارة نــوع ‪ ......‬يحمــل اللوحــة‬\n      ‫رقــم (‪( ).....‬عائــدة ملكيتهــا لوالــده ) متوقفــة ويســتقلها املدعــى عليــه‬\n      ‫فقــام املصــدر بالترجــل واالجتــاه إليــه وفتــح بــاب الســائق وقــام بتســليمه‬\n      ‫املبلــغ املرقــم واســتلم منــه قطعــة ســوداء اللــون يشــتبه أن تكــون مــن‬\n      ‫احلشــيش املخــدر بلــغ وزنهــا (‪ )4, 400‬أربعــة جرامــات وأربعمائــة‬\n      ‫مليجــرام ثــم عــاد وســلمها لرجــل األمــن املرافــق لــه فتمــت متابعتــه بعــد‬\n      ‫ذلــك واســتيقافه والقبــض عليــه وبتفتيــش ســيارته عثــر فــوق مقعــد‬\n      ‫املرافــق علــى قطعــة ســوداء اللــون يشــتبه أن تكــون مــن احلشــيش املخــدر‬\n      ‫بلــغ وزنهــا (‪ ) 800,2‬جرامــن وثمامنائــة مليجــرام كمــا عثــر علــى املبلــغ‬\n\n\n‫‪271‬‬\n\f‫املرقــم بالقــرب مــن (ناقــل احلركــة ) داخــل ســيارته ‪ .‬وقــد أثبــت التقريــر‬\n‫الكيميائــي الصــادر مــن املركــز اإلقليمــي ملراقبــة الســموم بالقصيــم‬\n‫رقــم(‪ )1221‬لعــام ‪1433‬ه ـ إيجابيــة مــا أرســل للتحليــل للحشــيش املخــدر‬\n‫املــدرج بجــدول املخــدرات وانتهــى التحقيــق معــه إلــى اتهامــه ببيــع قطعــة‬\n‫مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )4.400‬أربعــة جرامــات وأربعمائــة‬\n‫مليجــرام بقصــد االجتــار وحيازتــه لقطعــة مــن احلشــيش املخــدر بلــغ‬\n‫وزنهــا (‪ )2.800‬جرامــن وثمــان مئــة مليجــرام بقصــد التعاطــي‬\n‫والترويــج وتعاطيــه للحشــيش املخــدر واســتخدام هاتفــه النقــال مــن‬\n‫نــوع ‪ ) ..... (.......‬يحمــل الرقــم التسلســلي (‪ ).....‬ورقــم االتصــال (‪)......‬‬\n‫بالتنســيق لبيــع احملظــورات وذلــك لألدلــة والقرائــن املفصلــة يف الئحــة‬\n‫الدعــوى وباالطــاع علــى نتيجــة بحــث ســوابقه تبــن عــدم وجــود ســوابق‬\n‫جنائيــة مســجلة عليــه أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n‫بالعقوبــات التاليــة ‪:‬أو ًال ‪ :‬بالســجن واجللــد والغرامــة وفقـ ًا للفقــرة األولــى‬\n‫مــن املــادة (‪ )38‬وإعمــال املــادة (‪ )62‬ثاني ـاً‪ :‬مصــادرة جهــاز الهاتــف‬\n‫النقــال وشــريحة االتصــال املوصوفــن ثالث ـ ًا ‪ :‬مبنعــه مــن الســفر خــارج‬\n‫اململكــة بعــد تنفيــذ عقوبــة الســجن وفق ـ ًا للفقــرة األولــى مــن املــادة‬\n‫(‪ )56‬مــن نظــام املخــدرات هكــذا ادعــى املدعــي العــام وبســؤال املدعــى‬\n‫عليــه عــن دعــوى املدعــي العــام أجــاب بقولــه مــا ذكــره املدعــي العــام يف‬\n‫دعــواه مــن أننــي بعــت قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪)4.400‬‬\n‫أربعــة جرامــات وأربعمائــة مليجــرام وحــزت قطعــة مــن احلشــيش املخــدر‬\n‫بلــغ وزنهــا (‪ )2.800‬جرامــن وثمــان مئــة مليجــرام بقصــد التعاطــي‬\n‫وأننــي تعاطيــت احلشــيش املخــدر واســتخدمت هاتفــي النقــال ورقمــي‬\n‫املذكــور بالتنســيق لبيــع احملظــورات فهــذا كلــه صحيــح وقــد بعــت‬\n\n\n                                                                                         ‫‪272‬‬\n\f      ‫احلشــيش املذكــور بقصــد احلصــول علــى املــال وكانــت حيــازة القطعــة‬\n      ‫ذات الــوزن (‪ ) 2.800‬جرامــن وثمامنائــة مليجــرام بقصــد التعاطــي ال‬\n      ‫الترويــج وإننــي تائــب ونــادم علــى مــا أقدمــت عليــه وأتعهــد بعــدم العــودة‬\n      ‫إليــه هكــذا أجــاب املدعــى عليــه وبســؤال املدعــي العــام عــن البينــة‬\n      ‫علــى مــا أنكــره املدعــى عليــه مــن كــون القطعــة التــي وزنهــا (‪)2.800‬‬\n      ‫للترويــج أجــاب بقولــه لــدي مــا يف املعاملــة هكــذا أجــاب فتصفحــت‬\n      ‫املعاملــة فلــم أجــد فيهــا مــا يثبتــه ولــم يقــر بــه املدعــى عليــه يف إقــراره‬\n      ‫املصــدق وقــد وجــدت التقريــر الكيميائــي املشــار إليــه وهــو كمــا‬\n      ‫أشــار املدعــى العــام كمــا وجــدت أن صحيفــة املدعــى عليــه خاليــة مــن‬\n      ‫الســوابق فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي العــام املتضمنــة اتهــام‬\n      ‫املدعــى عليــه ببيــع قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪)4.400‬‬\n      ‫أربعــة جرامــات وأربعمائــة مليجــرام بقصــد االجتــار وحيازتــه لقطعــة‬\n      ‫مــن احلشــيش املخــدر بلــغ وزنهــا (‪ ) 2.800‬جرامــن وثمــان مئــة مليجــرام‬\n      ‫بقصــد التعاطــي والترويــج وتعاطيــه للحشــيش املخــدر واســتخدام هاتفــه‬\n      ‫النقــال ورقــم اتصالــه املذكــور بالتنســيق لبيــع احملظــورات وملصادقــة‬\n      ‫املدعــى عليــه علــى هــذه التهمــة ســوى دفعــه بــأن حيــازة القطعــة التــي‬\n      ‫وزنهــا (‪ )2.800‬جرامــن وثمامنائــة مليجــرام تعاطــي ولعــدم البينــة علــى‬\n      ‫كونهــا للترويــج وملــا جــاء يف املــادة ‪ 38‬مــن نظــام املخــدرات يف عقوبة بيع‬\n      ‫املخــدرات وترويجهــا وملــا جــاء يف املــادة ‪ 56‬مــن املنــع مــن الســفر ومــا جــاء‬\n      ‫يف املــادة ‪ 62‬مــن النظــام يف تداخــل العقوبــات ومــا قــرره أهــل العلم من أن‬\n      ‫التعازيــر تتداخــل ينظــر كشــاف القنــاع (‪ )124/6‬وملــا جــاء يف املــادة ‪60‬‬\n      ‫مــن النظــام مــن جــواز النــزول عــن احلــد األدنــى للعقوبــة املقــررة يف املــادة‬\n      ‫‪ 38‬مــن النظــام وألن املدعــى عليــه يســتحق هــذا النــزول إلبدائــه التوبــة‬\n\n\n‫‪273‬‬\n\f‫والنــدم وتعهــده بعــدم العــودة وألن ماضيــه خــال مــن الســوابق اجلنائيــة‬\n‫املســجلة وملــا تقــدم كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه ببيــع قطعــة‬\n‫مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )4.400‬أربعــة جرامــات وأربعمائــة‬\n‫مليجــرام بقصــد االجتــار وحيازتــه لقطعــة مــن احلشــيش املخــدر بلــغ‬\n‫وزنهــا (‪ )2.800‬جرامــن وثمامنائــة مليجــرام بقصــد التعاطــي وتعاطيــه‬\n‫للحشــيش املخــدر واســتخدام هاتفــه النقــال ورقــم اتصالــه املذكــور‬\n‫بالتنســيق لبيــع احملظــورات وقــررت جلــده ثمانــن جلــده دفعــة واحــدة‬\n‫علنــا حــدا للمســكر لتعاطيــه احلشــيش وتعزيــره علــى باقــي مــا أديــن بــه‬\n‫بســجنه ملــدة ســنتني يحســب منهــا مــدة توقيفــه يف هــذه القضيــة وجلــده‬\n‫مائتــن وخمســن جلــدة مفرقــة علــى خمــس مــرات كل مــرة خمســون‬\n‫جلــدة بــن كل مــرة واألخــرى خمســة عشــر يومــا وبــن جلــد احلــد وجلــد‬\n‫التعزيــر خمســة عشــر يومــا وتغرميــه خمســة آالف ريــال ومصــادرة هاتفــه‬\n‫النقــال ورقــم اتصالــه املذكوريــن ومنعــه مــن الســفر خــارج اململكــة ملدة‬\n‫ســنتني بعــد تنفيــذه الســجن ورددت باقــي دعــوى املدعــي العــام وبجميــع‬\n‫مــا تقــدم حكمــت وبعــرض احلكــم علــى املدعــى عليــه قنــع بــه وقــرر‬\n‫املدعــي العــام املعارضــة بالئحــة اعتراضيــة فجــرى إفهامــه بأنــه ســوف‬\n‫يــزود رســميا بصــورة مــن القــرار لتقــدمي الالئحــة خــال ثالثــن يومــا مــن‬\n‫تاريــخ اســتالمه فــإن لــم يقدمهــا خاللهــا رفــع احلكــم لالســتئناف بــدون‬\n‫الئحــة طبقــا للمــادة ‪ 195‬مــن نظــام اإلجــراءات اجلزائيــة وصلــى اهلل علــى‬\n                       ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بعنيــزة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بعنيــزة برقــم وتاريــخ ه ـ املقيــدة باحملكمــة برقــم وتاريــخ ه ـ ففــي يــوم‬\n\n\n                                                                                        ‫‪274‬‬\n\f      ‫األربعــاء املوافــق ه ـ فتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف بالقصيــم برقــم يف ه ـ وبرفقهــا قــرار محكمــة االســتئناف‬\n      ‫بالقصيــم رقــم يف ه ـ املتضمــن مــا نصــه بعــد املقدمــة وبدراســة القــرار‬\n      ‫وصــورة ضبطــه واوراق املعاملــة لــم يظهــر مــا يوجــب املالحظــة علــى مــا‬\n      ‫حكــم بــه فضيلتــه وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                        ‫أجمعــن و للمعلوميــة حــرر يف‬\n      ‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطَّ لعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة القصيــم علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة عنيــزة برقــم‬\n      ‫(‪ )............‬يف ه ـ ؛ املرفــق بهــا القــرار رقــم (‪ ).........‬يف ه ـ ؛ الصــادر مــن‬\n      ‫فضيلــة الشــيخ‪ /‬القاضــي يف احملكمــة؛ اخلــاص بدعــوى املدعــي العــام‬\n      ‫ضــد‪ /‬؛ التهامــه ببيــع احلشــيش املخــدر بقصــد االجتــار وحيازتــه بقصــد‬\n      ‫الترويــج والتعاطــي وتعاطيــه للحشــيش املخــدر‪ ،‬وقــد تضمــن القــرار‬\n      ‫حكــم فضيلتــه بإدانــة املدعــى عليــه مبــا نســب إليــه وحكــم بجلــده حــد‬\n      ‫املســكر ثمانــن جلــده وحكــم عليــه تعزيــر ًا بالســجن واجللــد والغرامــة‬\n      ‫املفصــل فيــه ؛‬\n                  ‫َّ‬      ‫املاليــة واملنــع مــن الســفر خــارج اململكــة ‪ ،‬علــى النحــو‬\n      ‫وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n      ‫لــم يظهــر مــا يوجــب املالحظــة علــى مــا حكــم بــه فضيلتــه‪ .‬واهلل املوفق‪،‬‬\n                               ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪275‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":269,"source_page_end":275,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fe9948b9ce93f7b54b849d8f97af82ad6acc4808d23f61c5551be42db8e228cd","normalized_text_hash":"bba895ea4015e46381978acd421ed2853162fadfd3613c192007b793c32b44cd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p269-33444872"},{"id":"e60f05cc-a45b-5a7a-8bdd-499cc4316aad","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -منح احلشيش املخدر مقابل احلصول على املساعدة -رجوع عن إقرار -تعزير املدعى عليه بالسجن واجللد والغرامة واملنع من السفر .","document_number":"34232119","case_number":"33611574","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/06","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -منح احلشيش املخدر مقابل احلصول على املساعدة -رجوع عن إقرار -تعزير املدعى عليه بالسجن واجللد والغرامة واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34232119 :‬تاريخه ‪1434/06/06:‬هـ‬\n                    ‫رقم الدعوى ‪33611574:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34353801‬تاريخه‪1434/11/09:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬منــح احلشــيش املخــدر مقابــل‬\n ‫احلصــول علــى املســاعدة ‪ -‬رجــوع عــن إقــرار ‪ -‬تعزيــر املدعــى عليــه‬\n                        ‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر ‪.‬‬\n\n\n\n          ‫‪( -‬لعن النبي صلى اهلل عليه وسلم ناقل اخلمر ) رواه أبو داود‪.‬‬\n             ‫‪ -‬املادة (‪ )38‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n             ‫‪ -‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n             ‫‪ -‬املادة (‪ )60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n ‫ادعــى املدعــي العــام علــى املدعــى عليــه بتســليم قطعــه مــن احلشــيش‬\n ‫املخــدر بقصــد الترويــج ‪ ،‬حيــث قبــض علــى املدعــى عليــه يف قضيــة‬\n ‫ســرقة‪ ،‬ومتــت معاجلتهــا يف دعــوى أخــرى ‪ ،‬أقــر املدعــى عليــه بأنــه أثنــاء‬\n ‫قيامــه بســرقة الســيارة ‪ ،‬طلــب مســاعدة أحــد األشــخاص مقابــل مبلــغ‬\n ‫مالــي وقطعــة مــن احلشــيش املخــدر‪ ،‬وحــن قــام مبســاعدته ســلمه قطعــة‬\n ‫احلشــيش ‪ ،‬وصــدق اعترافــه شــرع ًا بذلــك‪ ،‬وطلــب املدعــي العــام تعزيــر‬\n ‫املدعــى عليــه لذلــك بالســجن واجللــد والغرامــة واملنــع مــن الســفر‪،‬‬\n ‫أنكــر املدعــى عليــه مــا جــاء بدعــوى املدعــي العــام‪ ،‬باالطــاع علــى‬\n\n\n                                                                                     ‫‪276‬‬\n\f      ‫أوراق املعاملــة ‪ ،‬فوجــد مــن ضمنهــا إقــرار املدعــى عليــه املصــدق شــرع ًا‬\n      ‫بأنــه قــام بتســليم صاحــب الســيارة قطعــه احلشــيش مقابــل مســاعدته‪،‬‬\n      ‫وبعرضــه علــى املدعــى عليــه صــادق علــى صــدور اإلقــرار منــه‪ ،‬ودفــع‬\n      ‫بــأن هــذا كان باإلكــراه مــن قبــل البحــث اجلنائــي ولــم يســتطع إثبــات‬\n      ‫ذلــك‪ ،‬صــدر احلكــم علــى املدعــى عليــه بالســجن واجللــد والغرامــة‬\n      ‫واملنــع مــن الســفر‪ ،‬قــرر املدعــى عليــه واملدعــي العــام االعتــراض بالئحــة‬\n                        ‫اعتراضيــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمد هلل وحده وبعد فلدي أنا القاضي يف احملكمة اجلزائية بالرياض‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n      ‫بالريــاض برقــم وتاريــخ ‪ 1433/10/18‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫وتاريــخ ‪ 1433/10/18‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/05/04‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 09 : 45‬وفيهــا قــدم املدعــي العــام ‪ /‬الئحــة‬\n      ‫دعــوى عامــة ضــد ‪ ، ).....( /‬البالــغ مــن العمــر (‪ )19‬عام ـ ًا ‪ ،‬ســعودي‬\n      ‫اجلنســية الســجل املدنــي (‪ ،).....‬اعــزب ‪ ،‬طالــب ‪ ،‬يقيــم يف مدينــة (‪،).....‬‬\n      ‫أوقــف بتاريــخ ‪1433/4/12‬ه ـ وأحيــل إلــى شــعبه ســجن امللــز مبوجــب‬\n      ‫أمــر التوقيــف رقــم (‪ )6/9/476/2‬وتاريــخ ‪1433/5/17‬ه ـ الصــادر مــن‬\n      ‫مركــز شــرطة العليــا اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ‬\n      ‫‪1428/7/9‬ه ـ املبنــي علــى املــادة رقــم (‪ )112‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة حيــث انــه بتاريــخ ‪1433/4/12‬ه ـ قبــض علــى املذكــور مــن‬\n      ‫قبــل إحــدى فــرق ادارة التحريــات والبحــث اجلنائــي بشــرطة منطقــة‬\n      ‫الريــاض اثــر بــاغ بتاريــخ ‪1433/3/30‬ه ـ ملركــز شــرطة العليــا مفــادة‬\n\n‫‪277‬‬\n\f‫قيــام املذكــور بســرقة ســيارة أحــد األشــخاص (مت اعــداد الئحــة دعــوى‬\n‫عامــة فيمــا يتعلــق بالســرقة وأحيلــت إلــى احملكمــة اجلزئيــة بالريــاض‬\n‫مبوجــب اخلطــاب رقــم (ه ـ ر‪ )85086/6/1‬وتاريــخ (‪1433/8/10‬هــ)‬\n‫وقــد أقــر املذكــور بأنــه أثنــاء قيامــه بســرقة احــدى الســيارات طلــب‬\n‫مســاعدة شــخص يقــود ســيارة أجــرة مقابــل مبلــغ مالــي وقطعــة مــن‬\n‫احلشــيش املخــدر وبعــد انتهائــه مــن ســرقة الســيارة قــام بإعطائــه قطعــة‬\n‫مــن احلشــيش املخــدر وصــدق اعترافــه شــرع ًا وقــد أســفرت إجــراءات‬\n‫التحقيــق عــن توجيــه االتهــام إلــى األول‪ /‬بتســليم قطعــة مــن احلشــيش‬\n‫املخــدر بقصــد الترويــج املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n        ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وذلــك لألدلــة والقرائــن التاليــة ‪-:‬‬\n‫‪ -1‬ماتضمنــه اعترافــه املصــدق شــرع ًا املرفــق صــورة منــه علــى اللفــات‬\n                                                                           ‫رقــم (‪.)8-5‬‬\n               ‫وببحث سوابقه لم يعثر له على سوابق مسجلة حتى تاريخه‪.‬‬\n‫وحيــث إن مــا أق ــدم عل ــيه ال ــمذكور ف ــعل م ــحرم وم ــعاقب عليــه شــرع ًا‬\n       ‫ونظام ـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم باآلتــي ‪:‬‬\n‫‪ -1‬بعقوبــه الســجن واجللــد والغرامــة املاليــه بحقــه وفقـ ًا للفقــره (األولــى)‬\n‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء‬\n                                                                      ‫مــا أســند اليــه ‪.‬‬\n‫‪ -2‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء تنفيذ عقوبة ســجنه‬\n‫وفق ـ ًا للفقــرة (األولــى) مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n                                                                 ‫واملؤثــرات العقليــة‪.‬‬\n‫وبــاهلل التوفيــق وبســؤال املدعــى عليــه عــن الدعــوى أجــاب قائــا مــا‬\n\n\n                                                                                             ‫‪278‬‬\n\f      ‫ذكــره املدعــي العــام مــن القبــض وتاريخــه فصحيــح ومــا عــدا ذلــك‬\n      ‫فغيــر صحيــح والصحيــح أننــي لــم أطلــب مســاعدة شــخص يقــود ســيارة‬\n      ‫األجــرة مقابــل مبلــغ مالــي وقطعــة مــن احلشــيش املخــدر ولــم أســلم‬\n      ‫لســائق األجــرة قطعــة مــن احلشــيش وليــس علــي ســوابق مســجلة علــى‬\n      ‫هــذه إجابتــي وباالطــاع علــى أوراق املعاملــة ألفيــت ص ‪ 7‬مــن صــورة‬\n      ‫ملــف التحقيــق املطالبــة ألصلــه بختــم شــرطة العليــا إقــرار املدعــى عليــه‬\n      ‫املصــادق شــرع ًا مــن فضيلــة رئيــس هــذه احملكمــة واملتضمــن إقــراره‬\n      ‫بتســليم املدعــى عليــه صاحــب األجــرة قطعــة حشــيش مقابــل مســاعدته‬\n      ‫لــه أ ‪ .‬ه ـ بتصــرف وبعرضــه علــى املدعــى عليــه أجــاب قائال نعــم صادقت‬\n      ‫علــى هــذا اإلقــرار لكــن بإجبــار مــن البحــث اجلنائــي وباالطــاع علــى‬\n      ‫أوراق املعاملــة لــم أجــد تقريــر ًا كيميائي ـ ًا عــن احلشــيش املذكــور ثــم‬\n      ‫جــرى ســؤال املدعــى عليــه ألديــك بينــة علــى اإلكــراه فقــال ال فبنــاء‬\n      ‫علــى مــا ســلف مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه بتســليمه‬\n      ‫أحــد األشــخاص قطعــة حشــيش ورجوعــه عــن اإلقــرار ولعــدم قبــول‬\n      ‫رجوعــه إذا األصــل يف األقــوال االختيــار ولــم يثبــت ناقــل عنــه وال عتضــاء‬\n      ‫ذلــك بظاهــر انحــراف املســلك لوجــود قضيــة الســرقة املتعــددة وحلرمــة‬\n                                      ‫فعــل املدعــى عليــه و مشــروعية التعزيرعليــه‬\n      ‫وللعــن النبــي صلــى اهلل عليــه وســلم ناقــل اخلمــر كما ثبت عنــد أبي داود‬\n      ‫وملــا جــاء يف املــادة ( ‪ ) 60 ( ) 56 ( ) 38‬مــن نظــام مكافحــة املخــدرات‬\n      ‫ولقلــة الكميــة بظاهــر احلــال وعــدم وجــود ســوابق يف املخــدرات ولــن‬\n      ‫املدعــى عليــه فقــد ثبــت لــدي إدانــة املدعــى عليــه بتســليم قطعــة مــن‬\n      ‫احلشــيش بقصــد الترويــج وحكمــت عليــه لقــاء ذلــك بســجنه ســنتني‬\n      ‫تبــدأ مــن تاريــخ اإليقــاف وجلــده مائــة وخمســن جلــدة مفرقــة علــى‬\n\n\n‫‪279‬‬\n\f‫ثــاث دفعــات كل دفعــة أمــام النــاس قدرهــا خمســون جلــدة وبــن كل‬\n‫دفعتــن عشــرة أيــام بهــذه القضيــة وتغرميــه ألــف ريــال ومنعــه مــن الســفر‬\n‫خــارج اململكــة مــدة عامــن بعــد تنفيــذ عقوبــة الســجن وبعرضــه عليهمــا‬\n‫قــرر املدعــى عليــه القناعــة واملدعــى العــام االعتــراض مكتفيـ ًا بالئحــة‬\n‫الدعــوى وكان النطــق باحلكــم يف ‪ 1434 / 5 / 4‬ه ـ وأغلقــت اجللســة‬\n‫الســاعة العاشــرة والنصــف وعليــه جــرى التوقيــع وصلــى اهلل علــى نبينــا‬\n                                           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــه االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم وتاريــخ‬\n‫‪1434/10/8‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ ‪ ).....( /‬املســجل برقــم (‪ ).....‬وتاريــخ ‪1434/6/6‬ه ـ‬\n‫اخلــاص بدعــوى العــام ضــد (‪ ).....‬التهامــه بقضيــة مخــدرات علــى النحو‬\n‫املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‪.‬‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                 ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                    ‫‪280‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":276,"source_page_end":280,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ea25658dd3118ee02ea309663ae5e6e07f31e1185a25eec4228c6801baca588b","normalized_text_hash":"f8007eb63baaa4e1aec7f8f713950b1a4bd3d9460798da468d167b32c946317b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p276-34232119"},{"id":"c82998a5-8294-588c-acbe-203d0a9b3553","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -االجتار يف احلشيش املخدر -ترويج احلشيش املخدر -تعاطي احلشيش املخدر -شهادة الشهود -حد املسكر -إنكار الترويج وإقرار التعاطي -التعزير بالسجن واجللد -املنع من السفر -صرف النظر.","document_number":"341077","case_number":"33612199","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة اجلزائية الثانية برقم يف ه املتضمن املصادقة على احلكم","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/03","year":"1434","subject":"مخدرات -االجتار يف احلشيش املخدر -ترويج احلشيش املخدر -تعاطي احلشيش املخدر -شهادة الشهود -حد املسكر -إنكار الترويج وإقرار التعاطي -التعزير بالسجن واجللد -املنع من السفر -صرف النظر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"         ‫رقم الصك‪ 341077:‬تاريخه ‪1434/01/03:‬هـ‬\n                         ‫رقم الدعوى ‪33612199:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 34183316:‬تاريخه‪1434/04/09 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬االجتــار يف احلشــيش املخــدر ‪ -‬ترويــج احلشــيش املخــدر‬\n      ‫‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬شــهادة الشــهود ‪ -‬حــد املســكر ‪ -‬إنــكار‬\n      ‫الترويــج وإقــرار التعاطــي ‪ -‬التعزيــر بالســجن واجللــد ‪ -‬املنــع مــن‬\n                                                       ‫الســفر ‪ -‬صــرف النظــر‪.‬‬\n\n\n\n\n      ‫‪ - 1‬قــال شــيخ اإلســام ابــن تيميــة يف الفتــاوى (‪( :)135/29‬والصحيــح‬\n      ‫أن احلشيشــة مســكرة ‪ ،‬كالشــراب ‪ ،‬وأن آكلها يحد منها فهي خمر)‪.‬‬\n      ‫‪ - 2‬وقــال رحمــه اهلل يف الفتــاوى (‪( : )142/29‬وفيهــا مــن املفاســد مــا‬\n      ‫ليــس يف اخلمــر ‪ ،‬وإن كان يف اخلمــر مفســدة ‪،‬ليســت فيها‪،‬وهــي‬\n      ‫احلــدة ‪،‬فهــي بالتحــرمي أولــى مــن اخلمــر ‪ ،‬الن ضــرر آكل احلشيشــة‬\n      ‫علــى نفســه ‪ ،‬أشــد مــن ضــرر اخلمــر‪ ،‬وضــرر شــارب اخلمــر علــى النــاس‬\n      ‫أشــد ‪ ،‬إال أنــه يف هــذه األزمــان لكثــرة أكل احلشيشــة صــار الضــرر‬\n                                 ‫الــذي منهــا علــى النــاس أعظــم مــن اخلمــر )‪.‬‬\n              ‫‪ - 3‬املادة (‪ )1/56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n               ‫‪ - 4‬املادة (‪ )2/3‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n      ‫‪ - 5‬املــادة (‪ )30‬مــن الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات‬\n                                                             ‫واملؤثــرات العقليــة‪.‬‬\n\n\n\n‫‪281‬‬\n\f‫ادعــى املدعــي العــام علــى املدعــى عليــه ببيــع احلشــيش املخــدر‪ ،‬وتعاطــي‬\n‫احلشــيش املخــدر‪ ،‬تبلغــت اجلهــة األمنيــة مــن أحــد املصــادر الســرية عــن‬\n‫قيــام املدعــى عليــه بترويــج احلشــيش ‪ ،‬واســتعد املصــدر لإلطاحــة بــه ‪،‬‬\n‫واتصــل املصــدر علــى املدعــى عليــه وطلــب منــه حشيش ـ ًا مخــدر ًا مببلــغ‬\n‫(‪250‬مائتــن وخمســن ريــال )‪ ،‬ووافــق املدعــى عليــه علــى ذلــك ‪ ،‬وأبلــغ‬\n‫املصــدر بأنــه ســوف يقــوم بتوفيرهــا مــن شــخص آخــر ‪ ،‬ومت تزويــد‬\n‫املصــدر باملبلــغ املرقــم ‪ ،‬وتفتيشــه‪ ،‬وتكليــف أحــد األفــراد مبرافقتــه‪،‬‬\n‫ويف مــكان آخــر ‪ ،‬ســلم املدعــى عليــه للمصــدر واجلنــدي املرافــق لــه‬\n‫قطعــة بلــغ وزنهــا (‪ ) 6.6‬ســتة جرامــات وســتة بالعشــرة مــن اجلــرام ثبــت‬\n‫إيجابيتهــا للحشــيش املخــدر ‪ ،‬ومت القبــض عليــه وعثــر معــه علــى اجلــوال‬\n‫املســتخدم يف عمليــة البيــع‪ ،‬وطلــب املدعــي العــام تعزيــر املدعــى عليــه‬\n‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة جهــاز اجلــوال‬\n‫وإلزامــه بإعــادة املبلــغ احلكومــي وإلغــاء الشــريحة الصــادرة باســمه‪،‬‬\n‫أنكــر املدعــى عليــه مــا جــاء بدعــوى املدعــي العــام بخصــوص الترويــج‪،‬‬\n‫وأقــر بتعاطيــه احلشــيش املخــدر‪ ،‬بطلــب البينــة مــن املدعــي العــام علــى‬\n‫دعــواه أحضــر شــاهد ًا واحــد يشــهد بصحــة الواقعــة‪ ،‬صــدر احلكــم‬\n‫بحــد املســكر علــى املدعــى عليــه‪ ،‬واحلكــم بتعزيــر املدعــى عليــه‬\n‫بالســجن واجللــد‪ ،‬واحلكــم مبنعــه للســفر مــده مماثلــة ملــدة ســجنه بعــد‬\n          ‫انتهــاء محكوميتــه‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                   ‫‪282‬‬\n\f      ‫احلمــد هلل و حــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n      ‫لــدي أنــا ‪ ........‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة‬\n      ‫الــواردة مــن هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمــة‬\n      ‫برقــم ‪ ......‬وتاريــخ ‪ .......‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالدمــام برقــم ‪ ......‬وتاريــخ ‪ ......‬ه ـ افتتحــت اجللســة يف يــوم‬\n      ‫الثالثــاء ‪ ......‬ه ـ الســاعة احلاديــة عشــرة وفيهــا قــدم املدعــي العــام ‪......‬‬\n      ‫ا فيهــا بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام لفــرع‬‫دعــواه قائ ـ ً‬\n      ‫املنطقــة الشــرقية أدعــي علــى‪ .......... /‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ........‬حيــث إنــه باالطــاع علــى محضــر القبــض املعــد مــن‬\n      ‫قبــل مكافحــة املخــدرات بالدمــام تبــن أنــه بتاريــخ ‪ ........‬ه ـ ورد بــاغ‬\n      ‫مــن أحــد املصــادر الســرية مفــاده أن املدعــى عليــه يعمــل بائــع جــوالت يف‬\n      ‫ســوق بالدمــام ويقــوم بترويــج احلشــيش املخــدر مســتخدم ًا يف ذلــك جواله‬\n      ‫ذي الرقــم (‪ ).....‬واســتعد املصــدر باإلطاحــة بــه باجلــرم املشــهود واتصــل‬\n      ‫عليــه وطلــب منــه حشيش ـ ًا مخــدر ًا مببلــغ مائتــن وخمســن ريــا ًال فــرد‬\n      ‫عليــه املدعــى عليــه بأنــه ســوف يوفرهــا مــن شــخص وســتكون عنــده‬\n      ‫بعــد نصــف ســاعة ثــم مت تفتيــش املصــدر وزود باملبلــغ املرقــم واجتــه‬\n      ‫برفقــة أحــد أفــراد املكافحــة حتــت أنظــار الفرقــة ودخــا إلــى منــزل‬\n      ‫املصــدر حيــث إنــه هــو املوقــع املتفــق عليــه للمقابلــة مــع املدعــى عليــه‬\n      ‫وبعــد نصــف ســاعة توقفــت ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم (‪).....‬‬\n      ‫وترجــل منهــا املدعــى عليــه ودخــل منــزل املصــدر وقابــل املصــدر ورجــل‬\n      ‫األمــن املرافــق لــه وســلمهما قطعــة بلــغ وزنهــا ( ‪ )6,6‬ســتة جرامــات وســتة‬\n\n‫‪283‬‬\n\f‫بالعشــرة مــن اجلــرام أثبــت التقريــر الكيمــاوي رقــم (‪ 3241‬ك ش)‬\n‫وتاريــخ ‪ .......‬ه ـ ايجابيتهــا ملــادة احلشــيش املخــدر وقــد خــرج املدعــى عليــه‬\n‫ســريع ًا ولــم تســتطع الفرقــة القبــض عليــه يف حينــه وبتاريــخ ه ـ شــوهد‬\n‫بالقــرب مــن ســوق ‪ ......‬بالدمــام ومت القبــض عليــه وعثــر معه على الهاتف‬\n‫اجلــوال املســتخدم يف عمليــة البيــع والــذي مــن نــوع (‪ ).....‬ويحمــل الرقــم‬\n‫املصنعــي (‪ )......‬ورقــم شــريحته (‪ )......‬وبســماع أقوالــه واســتجوابه أقــر‬\n‫بأنــه يتعاطــى احلشــيش املخــدر وأن الســيارة التــي حضــر عليهــا تعــود‬\n‫لشــقيقه ونفــى مــا ســوى ذلــك وقــد انتهــى التحقيــق إلــى اتهــام املدعــى‬\n‫عليــه باآلتــي‪ -1 :‬بيــع (‪ )6,6‬ســتة جرامــات وســتة بالعشــرة مــن اجلــرام‬\n‫مــن احلشــيش املخــدر بقصــد االجتــار ‪ -2‬تعاطــي احلشــيش املخــدر وذلــك‬\n‫لألدلــة والقرائــن التاليــة‪ -1 :‬محاضــر البــاغ واالتصــال والقبــض‬\n‫القبــض املنــوه عنهــا املدونــة علــى الصفحــة (‪ )2،4،12،13‬مــن امللــف‬\n‫املرفــق علــى اللفــة رقــم (‪ -2 )1‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه‬\n‫املرفــق علــى اللفــة رقــم (‪ -3 )9‬العثــور علــى اجلــوال الــذي مت تنســيق‬\n‫عمليــة البيــع عليــه مــع املدعــى عليــه قرينــة علــى صحــة االتهــام وبالبحــث‬\n‫عــن ســوابقه لــم يعثــر لــه علــى ســوابق وحيــث إن مــا أقــدم عليــه املدعــى‬\n‫عليــه وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه‬\n‫شــرعا ونظامــا أطلــب مــا يلــي‪ :‬أوالً‪ :‬إثبــات قيامــه ببيــع (‪ )6,6‬ســتة‬\n‫جرامــات وســتة بالعشــرة مــن اجلــرام مــن احلشــيش املخــدر بقصــد االجتار‬\n‫وتعاطيــه ملــادة احلشــيش املخــدر واحلكــم عليــه باآلتي‪1 :‬ـ بعقوبة الســجن‬\n‫واجللــد والغرامــة وفــق الفقــرة رقــم (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام‬\n‫مكافحــة املخــدرات واالكتفــاء بالعقوبــة األشــد وفقـ ًا للفقــرة رقــم (‪)1‬‬\n‫مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات ‪2‬ـ منعــه مــن الســفر وفــق‬\n\n\n                                                                                         ‫‪284‬‬\n\f      ‫الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن النظــام ‪3‬ـ مصــادرة الهاتــف اجلــوال‬\n      ‫املســتخدم يف عمليــة البيــع املوضــح نوعــه ورقمــه املصنعــي يف الوقائــع‬\n      ‫وفــق الفقــرة رقــم (‪ )1‬مــن املــادة (‪ )53‬مــن النظــام‪ .‬ثانياً‪ :‬اســقاط شــريحة‬\n      ‫الهاتــف اجلــوال وعــدم صرفهــا للمدعــى عليــه مــرة أخــرى وفــق تعميــم‬\n      ‫وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬هــ‪ .‬ثالث ـاً‪ :‬إلزامــه‬\n      ‫بدفــع مبلــغ مالــي (‪ )250‬ريــال بــد ًال عــن املبلــغ احلكومــي املرقــم الــذي‬\n      ‫لــم يتــم العثــور عليــه وفــق تعميــم وزيــر الداخليــة رقــم (‪)15980/4/5/1‬‬\n      ‫وتاريــخ ‪1428/10/23-22‬ه ـ هكــذا ادعــى وبعــرض الدعــوى علــى‬\n      ‫ا مــا ذكــره املدعــي العــام مــن قيامــي ببيــع‬   ‫املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫احلشــيش فذلــك غيــر صحيــح وأمــا تعاطــي احلشــيش فذلــك صحيــح‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي العــام قــال مــا ذكــره املدعــى‬\n      ‫عليــه غيــر صحيــح والصحيــح مــا ذكــرت يف دعــواي هكــذا أجــاب ثــم‬\n      ‫جــرى ســؤال املدعــي العــام البينــة علــى دعــواه فقــال أطلــب مهلــة‬\n      ‫إلحضارهــا ولــذا رفعــت اجللســة ويف جلســة أخــرى افتتحــت اجللســة وفيها‬\n      ‫حضــر الطرفــان ثــم جــرى ســؤال املدعــي العــام عمــا طلــب االســتمهال‬\n      ‫ألجلــه فقــال إننــي أحضــرت معــي أحــد أعضــاء الفرقــة القابضــة وأطلــب‬\n      ‫ســماع مــا لديــه وهــو هــذا احلاضــر‪ /‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم وبســؤال الشــاهد عمــا لديــه مــن شــهادة قــال ( أشــهد بــاهلل‬\n      ‫أنــه وردنــا بــاغ مــن أحــد املصــادر الســرية مفــاده أن املدعــى عليــه يعمــل‬\n      ‫بائــع جــوالت يف ســوق ‪ ....‬بالدمــام ويقــوم بترويــج احلشــيش املخــدر‬\n      ‫مســتخدم ًا يف ذلــك جوالــه واســتعد املصــدر باإلطاحــة بــه باجلرم املشــهود‬\n      ‫واتصــل عليــه وطلــب منــه حشيشـ ًا مخــدر ًا مببلــغ مائتــن وخمســن ريــا ًال‬\n      ‫فــرد عليــه املدعــى عليــه بأنــه ســوف يوفرهــا مــن شــخص وســتكون‬\n\n\n‫‪285‬‬\n\f‫عنــده بعــد نصــف ســاعة ثــم مت تفتيــش املصــدر وزود باملبلــغ املرقم واجته‬\n‫برفقتــي ودخلنــا إلــى منــزل املصــدر حيــث إنــه هــو املوقــع املتفــق عليــه‬\n‫للمقابلــة مــع املدعــى عليــه وبعــد نصــف ســاعة توقفــت ســيارة مــن نــوع‬\n‫‪ ......‬وترجــل منهــا املدعــى عليــه ودخــل منــزل املصــدر وقابــل املصــدر‬\n‫وســلمه قطعــة احلشــيش املخــدر واســتلم مــن املصــدر املبلــغ ثــم خــرج‬\n‫املدعــى عليــه ســريع ًا ولــم تســتطع الفرقــة القبــض عليــه يف حينــه )‬\n‫هكــذا شــهد ثــم جــرى ســؤال املدعــي العــام هــل لديــه زيــادة بينــة فقــال‬\n‫أطلــب الرجــوع إلــى املعاملــة هكــذا أجــاب ثــم جــرى عــرض الشــاهد‬\n‫وشــهادته علــى املدعــى عليــه فقــال الشــاهد ال أعرفــه ولــم أره وشــهادته‬\n‫غيــر صحيحــة هكــذا أجــاب ثــم جــرى رفــع اجللســة للتأمــل ويف يــوم‬\n‫الســبت ه ـ افتتحــت اجللســة وفيهــا حضــر الطرفــان ثــم جــرى االطــاع‬\n‫علــى املعاملــة فوجــدت علــى لفــة رقــم (‪ )1‬دفتــر التحقيــق ص (‪)13-12‬‬\n‫محضــر انتقــال وقبــض وتفتيــش وهــو طبــق مــا ذكــر املدعــي العــام يف‬\n‫دعــواه كمــا وجــدت علــى لفــة رقــم (‪ )10‬تقريــر كيمــاوي شــرعي رقــم‬\n‫(‪3241‬ك ش) املتضمــن ايجابيــة العينــة املرســلة للحشــيش املخــدر كمــا‬\n‫وجــدت علــى لفــة رقــم (‪ )15‬كــرت بصمــات املدعــى عليــه املتضمــن‬\n‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي العــام‬ ‫عــدم وجــود ســوابق لــه فبنـ ً‬\n‫وإجابــة املدعــى عليــه ونظــر ًا لعــدم اكتمــال بينــة املدعــي العــام علــى‬\n‫ـاء علــى‬\n       ‫دعــواه ومبــا أن املدعــي العــام لــم يحضــر إال شــاهد واحــد وبنـ ً‬\n‫محضــر القبــض والتفتيــش وبنــاء علــى الفقــرة (‪ )2‬من املــادة (‪ )3‬والفقرة‬\n‫(‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات املؤثــرات العقلــي‬\n‫وبنــاء علــى املــادة (‪ )30‬مــن الالئحــة التنفيذيــة لنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة ومبــا أن احلشــيش مســكر حيــث ذكــر‬\n\n\n                                                                                      ‫‪286‬‬\n\f      ‫شــيخ اإلســام ابــن تيميــة يف مجمــوع الفتــاوى مــا نصــه‪( :‬والصحيــح أن‬\n      ‫احلشيشــة مســكرة كالشــراب وأن آكلهــا يحــد منهــا فهــي خمــر )‬\n      ‫(ج‪/29‬ص‪ )135‬كمــا قــال‪( :‬وفيهــا مــن املفاســد مــا ليــس يف اخلمــر وإن‬\n      ‫كان يف اخلمــر مفســدة ليســت فيهــا وهــي احلــدة فهــي بالتحــرمي أولــى مــن‬\n      ‫اخلمــر ألن ضــرر آكل احلشيشــة علــى نفســه أشــد مــن ضــرر اخلمــر‬\n      ‫وضــرر شــارب اخلمــر علــى النــاس أشــد إال أنــه يف هــذه األزمــان لكثــرة‬\n      ‫أكل احلشيشــة صــار الضــرر الــذي منهــا علــى النــاس أعظــم مــن اخلمــر)‬\n      ‫مجمــوع الفتــاوى (ج‪/29‬ص‪ )142‬لــذا فقــد ثبــت لــدي تعاطــي املدعــى‬\n      ‫عليــه للحشــيش املخــدر ولــم تثبــت لــدي إدانتــه ببيــع احلشــيش املخــدر‬\n      ‫ونظــر ًا لوجــود الشــبهة وقــوة القرائــن التــي قدمهمــا املدعــي العــام يف‬\n      ‫قيــام املدعــى عليــه بالترويــج فقــد قــررت اآلتــي‪ :‬أوالً‪ :‬صرفــت النظــر‬\n      ‫عــن مطالبــة املدعــي العــام بتطبيــق الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة‬\n      ‫(‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫وعــن مطالبتــه بإعــادة املبلــغ احلكومــي لعــدم ثبوتهــا‪ .‬ثانيـاً‪ :‬جلــد املدعــى‬\n      ‫عليــه ثمانــن جلــدة دفعــة واحــدة حــد املســكر ويكــون التنفيــذ يف‬\n      ‫مــكان عــام يحضــره جمــع مــن النــاس لقــاء شــربه احلشــيش املســكر‪.‬‬\n      ‫ـداء مــن تاريــخ إيقافــه‬\n                              ‫ثالث ـاً‪ :‬ســجنه ملــدة ثــاث ســنوات وســتة أشــهر ابتـ ً‬\n      ‫وجلــده مائتــي جلــدة تعزيــر ًا مفرقــة علــى أربــع دفعــات متســاوية بــن كل‬\n      ‫دفعــة وأخــرى مــدة التقــل عــن عشــرة أيــام لقــاء شــبهة البيــع‪ .‬رابعـاً‪ :‬منعــه‬\n      ‫مــن الســفر ملــدة ســنتني تبــدأ بعــد انتهــاء فتــرة الســجن املقــررة يف حقــه‬\n      ‫يف البنــد ثالث ـاً‪ .‬وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن قــرر‬\n      ‫املدعــى عليــه واملدعــي العــام االعتــراض علــى احلكــم وطلبــا االســتئناف‬\n      ‫بالئحــة يقدمهــا كل واحــد منهمــا فجــرى إفهامهمــا بأنــه ســوف يجــري‬\n\n\n‫‪287‬‬\n\f‫بعــد قليــل تســليم كل واحــد منهمــا نســخة مــن احلكــم لتقــدمي الالئحــة‬\n‫االعتراضيــة خــال ثالثــن يوم ـ ًا يكــون حقــه يف االعتــراض بعدهــا‬\n‫ســاقط ًا ففهمــا ذلــك وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر ‪ ........‬ه ـ احلمــد هلل وحــده وبعــد ففــي يــوم‬\n‫اإلثنــن ‪ .........‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــى عليــه وقــرر‬\n‫العــدول عــن اعتراضــه وأنــه موافــق علــى احلكــم هكــذا قــرر وأمــا‬\n‫املدعــي العــام فلــم يقــدم اعتراضــه علــى احلكــم وقــد مضــت املــدة‬\n‫النظاميــة لالعتــراض لــذا فقــد ســقط حقــه يف االعتــراض وأمــرت برفــع‬\n‫املعاملــة إلــى محكمــة االســتئناف وذلــك بنــاء علــى املــادة (‪ )195‬مــن‬\n‫نظــام اإلجــراءات اجلزائيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ه ـ احلمــد هلل وحــده وبعــد ففــي يــوم‬\n‫الســبت ه ـ الســاعة الثانيــة عشــرة والنصــف افتتحــت اجللســة وفيهــا‬\n‫وردتنــا املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا‬\n‫القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم يف ه ـ املتضمــن مــا‬\n‫نصــه‪( :‬لوحــظ أن فضيلتــه لــم يعمــل مبقتضــى املــادة ‪ 56‬مــن نظــام‬\n‫املخــدرات ملالحظــة ذلــك وإعــادة املعاملــة إلكمــال الزمهــا) عليــه أجيــب‬\n‫أصحــاب الفضيلــة بأننــي قــد رجعــت عمــا حكمــت بــه ســابق ًا يف البنــد‬\n‫رابع ـ ًا وحكمــت مبــا يلــي‪ :‬رابع ـاً‪ :‬منــع املدعــى عليــه مــن الســفر ملــدة‬\n‫ثــاث ســنوات وســتة أشــهر تبــدأ بعــد انتهــاء فتــرة الســحن املقــررة يف‬\n‫حقــه يف البنــد ثالثـاً‪ .‬وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n‫القناعــة باحلكــم وأمــا املدعــي العــام فقــرر االعتــراض واالكتفــاء‬\n‫بالئحــة الدعــوى العامــة وأمــرت بإحلــاق ذلــك بالقــرار ورفــع املعاملــة إلــى‬\n‫محكمــة االســتئناف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n\n\n                                                                                        ‫‪288‬‬\n\f      ‫محمــد‪ .‬حــرر يف ه ـ احلمــد هلل وحــده وبعــد ففــي يــوم الســبت ه ـ افتتحــت‬\n      ‫اجللســة الســاعة الثانيــة إال ربــع وفيهــا وردتنــا املعاملــة مــن محكمــة‬\n      ‫االســتئناف باملنطقــة الشــرقية برقــم يف ه ـ وبرفقهــا القــرار الصــادر مــن‬\n      ‫الدائــرة اجلزائيــة الثانيــة برقــم يف ه ـ املتضمــن املصادقــة علــى احلكــم‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                         ‫وسلم‪ .‬حرر يف هـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم وتاريــخ ه ـ الــواردة مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة مبدينــة الدمــام برقــم وتاريــخ ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ ........ /‬املســجل برقــم وتاريــخ ه ـ‬\n      ‫اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ /‬املدعــى عليــه يف قضيــة مخــدرات‬\n      ‫وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n      ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا‬\n      ‫أجــاب بــه فضيلتــه علــى قرارنــا رقــم ج‪/2‬ب وتاريــخ ه ـ قررنــا املصادقــة‬\n      ‫علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                           ‫محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف‪.......‬‬\n\n\n\n\n‫‪289‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":281,"source_page_end":289,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cd01efbc4a4d6a8d2b2ba125358606a655a5e9d60cacb4bc15b24e528a877a91","normalized_text_hash":"485aebab824d72139d3b8cba706518ab469b017e461ddafb7cd17596be9c62f4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p281-341077"},{"id":"61ad0b7e-bbe2-5893-a946-f756532534d1","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب بقصد الترويج -قات -نص التعميم القضائي على عدم إطالة سجن األجنبي -التعزير بالسجن واجللد والغرامة وإبعادهم عن الباد بعد إنفاذ العقوبة .","document_number":"34330070","case_number":"33663671","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بجازان املكلف ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/13","year":"1434","subject":"مخدرات -تهريب بقصد الترويج -قات -نص التعميم القضائي على عدم إطالة سجن األجنبي -التعزير بالسجن واجللد والغرامة وإبعادهم عن الباد بعد إنفاذ العقوبة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34330070 :‬تاريخه‪1434/10/13 :‬هـ‬\n                    ‫رقم الدعوى‪33663671 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34357962‬تاريخه‪1434/11/11 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬تهريــب بقصــد الترويــج ‪ -‬قــات ‪ -‬نــص التعميــم القضائــي‬\n ‫علــى عــدم إطالــة ســجن األجنبــي‪ -‬التعزيــر بالســجن واجللــد والغرامــة‬\n                              ‫وإبعادهــم عــن البــاد بعــد إنفــاذ العقوبــة ‪.‬‬\n\n\n\n                 ‫‪ -1‬األمر السامي الكرمي رقم (‪ )59633‬يف ‪1432/12/9‬هـ‪.‬‬\n                         ‫‪ -2‬قرار مجلس الوزراء رقم (‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n ‫‪ -3‬الفقــرة (أ) مــن املــادة األولــى مــن قــرار وزيــر الداخليــة رقــم ( ‪) 2057‬‬\n                                                                ‫يف ‪1404/5/26‬هـ ‪.‬‬\n\n\n\n ‫ادعــى املدعــي العــام علــى املدعــى عليهــم بتهريــب القــات مــن األراضــي‬\n ‫اليمنيــة إلــى األراضــي الســعودية بقصــد االجتــار ‪ ،‬طلــب إثبــات مــا‬\n ‫أســند إليهــم واحلكــم بتعزيرهــم وإبعادهــم عــن البــاد بعــد انتهــاء‬\n ‫محاكمتهم‪،‬حيــث قبــض علــى املدعــى عليهــم أثنــاء قدومهــم مــن اليمــن‬\n ‫إلــى الســعودية وبتفتيشــهم ضبــط بحوزتهــم كميــة مــن نبــات القــات‬\n ‫وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املضبوطــة لنبــات‬\n ‫القــات احملظــور ‪،‬وصــادق املدعــى عليهــم باالدعــاء املوجــه إليهــم بتهريب‬\n ‫القــات حلســاب الغيــر مقابــل مبلــغ مالــي بقصــد الترويــج ‪،‬وبنــاء علــى مــا‬\n\n\n                                                                                       ‫‪290‬‬\n\f      ‫تقــدم حكمــت احملكمــة بتعزيرهــم بالســجن ثالثــن شــهر ًا وجلــد كل‬\n      ‫واحــد منهــم خمســمائة جلــدة علن ـ ًا مفرقــة كل دفعــة خمســون جلــدة‬\n      ‫وغرامــة ماليــة يدفعهــا كل وحــد منهــم قدرهــا خمســة آالف ريــال تــودع‬\n      ‫يف بيــت مــال املســلمني وإبعادهــم عــن البــاد بعــد إنفــاذ العقوبــة املقــررة‬\n      ‫بحقهــم وقنــع املدعــى عليهــم باحلكــم واعتــرض املدعــي العــام مكتفيـ ًا‬\n                   ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬    ‫بالئحــة الدعــوى ُ‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بجــازان بنــاء علــى املعاملــة الــواردة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بجــازان املكلــف برقــم ‪ 341489478‬وتاريــخ ‪1434/8/17‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم‪ 342044360‬وتاريــخ ‪1434/8/24‬ه ـ املتعلقــة‬\n      ‫بدعــوى املدعــي العــام ضد‪.....‬ورفقــاه املتهمــن يف قضيــة قــات احملكــوم‬\n      ‫فيهــا مــن قبــل قضــاة احملكمــة العامة بالصك الشــرعي رقــم ‪3441970‬‬\n      ‫وتاريــخ ‪1434/2/19‬ه ـ بعــدم االختصــاص واختصاصنــا بنظرهــا‬\n      ‫واملصــدق مــن قضــاة الدائــرة الثانيــة مبحكمــة االســتئناف مبنطقــة‬\n      ‫عســير بقرارهــم رقــم ‪ 34222163‬وتاريــخ ‪1434/5/26‬ه ـ عليــه ففــي‬\n      ‫يــوم اخلميــس املوافــق ‪1434/10/8‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 00‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪.....‬بالتعميــد رقــم (‪ ).....‬يف ‪1431/8/13‬ه ـ‬\n      ‫ال مــن ‪.....‬مينــي اجلنســية مبوجــب البطاقــة البديلــة‬‫واملدعــى عليهــم ك ً‬\n      ‫رقــم(‪ ).....‬و‪.....‬مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم(‪ ).....‬و‪.....‬‬\n      ‫مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم(‪ ).....‬وقــدم املدعــي العــام‬\n      ‫دعــوى محــررة تتضمــن‪ :‬إنــه بتاريــخ ‪1432/9/17‬ه ـ وأثنــاء قيــام إحــدى‬\n\n‫‪291‬‬\n\f‫دوريــات فصيــل األمــن واالســتخبارات بحــرس احلــدود بواجبهــا يف املوقــع‬\n‫املســمى ‪.....‬ألقــت القبــض علــى املدعــى عليهــم أعــاه أثنــاء قدومهــم مــن‬\n‫األراضــي اليمنيــة إلــى األراضــي الســعودية ســير ًا علــى األقــدام وبطريقــة‬\n‫غيــر مشــروعة وبتفتيشــهم ضبــط مــع األول(‪ ).....‬كميــة مــن نبــات‬\n‫القــات احملظــور بلــغ وزنهــا (‪15‬كجــم) خمســة عشــر كيلــو جرامـ ًا ومــع‬\n‫الثانــي (‪ ).....‬كميــة مــن نبــات القــات احملظــور بلــغ وزنها(‪15‬كجــم)‬\n‫خمســة عشــر كيلــو جرامـ ًا ومــع الثالــث (‪ ).....‬كميــة مــن نبــات القــات‬\n‫احملظــور بلــغ وزنها(‪10‬كجــم) عشــرة كيلــو جرام ـ ًا وأثبــت التقريــر‬\n‫الكيميائــي الشــرعي رقــم (‪ ).....‬وتاريــخ ‪1432/10/26‬ه ـ إيجابيــة‬\n‫العينــات املرســلة منهــا لنبــات القــات احملظــور وصــدر بشــأنهم قــرار‬\n‫اللجنــة اإلداريــة بحــرس احلــدود رقــم (‪ ).....‬وتاريــخ ‪1432/10/30‬ه ـ‬\n‫املتضمــن ســجن األول والثانــي بالســجن ملــدة (ســتة أشــهر) وســجن‬\n‫الثالث مدة (أربعة أشــهر) ملخالفتهم للمادة اخلامســة عشــرة من الالئحة‬\n‫التنفيذيــة لنظــام أمــن احلــدود وباســتجواب املدعــى عليهــم ومواجهتهــم‬\n‫بالتهــم املنســوبة إليهــم أقــروا بتهريبهــم لكميــة نبــات القــات املضبوطــة‬\n‫بحــوزة كل واحــد منهــم حصلــوا عليهــا مــن اليمــن لغــرض إيصالهــا‬\n‫قريــة ‪.....‬بالســعودية مقابــل مبلــغ وقــدره (‪200‬ريــال) لــكل واحــد منهــم‬\n‫وقــد صادقــوا علــى أقوالهــم حتقيق ـ ًا وقــد أســفر التحقيــق مــع املدعــى‬\n‫عليهــم بتوجيــه االتهــام إلــى األول والثانــي بتهريــب كل واحــد منهمــا‬\n‫مــا وزنــه خمســة عشــر كيلــو جرامـ ًا مــن نبــات القــات احملظــور وتهريــب‬\n‫الثالــث مــا وزنــه عشــرة كيلــو جرام ـ ًا مــن نبــات القــات احملظــور مــن‬\n‫اليمــن إلــى الســعودية بقصــد االجتــار املجــرم مبوجــب الفقــرة (األولــى)‬\n‫مــن املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n\n\n                                                                                    ‫‪292‬‬\n\f      ‫الصــادر باملرســوم امللكــي رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة‪ -1 :‬مــا جــاء بأقوالهــم املنــوه عنهــا واملونــة‬\n      ‫بدفتــر التحقيــق املرفــق لفــة (‪ )51‬واعترافاتهــم لــدى اجلهــة القابضــة لفــة‬\n      ‫رقــم (‪ -2 )7-1‬مــا جــاء مبحضــر القبــض والتفتيــش املرفــق لفــة (‪)8‬‬\n      ‫‪-3‬مــا ورد بالتقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة (‪)52‬‬\n      ‫وبالبحــث عــن ســوابقهم لــم يعثــر لــأول والثالــث علــى ســوابق مســجلة‬\n      ‫وعثــر للثانــي علــى ســابقة واحــدة حيــازة قــات وحيــث إن مــا أقــدم عليــه‬\n      ‫املذكــورون فعــل محــرم شــرع ًا ومعاقــب عليــه نظام ـ ًا مبوجــب قــرار‬\n      ‫مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات لــذا‬\n      ‫أطلــب إثبــات إدانتهــم مبــا أســند إليهــم واحلكــم عليهــم بالعقوبــة الــواردة‬\n      ‫بالفقــرة (أ) مــن املــادة (األولــى) مــن القــرار الــوزاري املشــار إليــه أعــاه‬\n      ‫إنفــاذ ًا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ‬\n      ‫واحلكــم بإبعادهــم عــن البــاد بعــد انتهــاء محكوميتهــم اســتناد ًا لــذات‬\n      ‫املــادة املذكــورة هكــذا ادعــى املدعــي العــام وبســؤال املدعــى عليهمــا‬\n      ‫‪.....‬و‪.....‬مينــي اجلنســية أجابــا باالعتــراف بتهريــب كل واحــد منهمــا ملــا‬\n      ‫وزنــه خمســة عشــر كيلــو جرامـ ًا وأجــاب املدعــى عيــه الثالــث ‪.....‬مينــي‬\n      ‫اجلنســية باالعتــراف بتهريــب مــا وزنــه عشــرة كيلــو جرام ـ ًا اجلميــع مــن‬\n      ‫نبــات القــات احملظــور مــن األراضــي اليمنيــة إلــى األراضــي الســعودية‬\n      ‫حلســاب الغيــر مقابــل مبلــغ مالــي هكــذا أجابــوا عنــد ذلــك جــرى منــا‬\n      ‫االطــاع علــى التقريــر الكيميائــي الشــرعي وعلــى محضــري الــوزن‬\n      ‫ـاء علــى‬ ‫والقبــض فوجــدت متطابقــة ملــا جــاء بدعــوى املدعــي العــام وبنـ ً‬\n      ‫مــا ذكــر مــن دعــوى املدعــي العــام وعلــى إجابــة املدعــى عليهمــا األول‬\n      ‫والثانــي باالعتــراف بتهريــب كل واحــد منهمــا مــا وزنــه خمســة عشــر‬\n\n\n‫‪293‬‬\n\f‫كيلــو جرام ـ ًا مــن نبــات القــات احملظــور وإجابــة املدعــى عليــه الثالــث‬\n‫باالعتــراف بتهريــب مــا وزنــه عشــرة كيلــو جرام ـ ًا مــن نبــات القــات‬\n‫احملظــور اجلميــع قامــوا بتهريــب الكميــات املذكــورة مــن األراضــي‬\n‫اليمنية إلى األراضي الســعودية حلســاب الغير مقابل مبلغ مالي لذا فقد‬\n‫ثبــت لــدي شــرع ًا إدانــة املدعــى عليهــم املذكوريــن بتهريــب كل واحــد‬\n‫منهــم لكميــة نبــات القــات املوضحــة أعــاه مــن اليمــن إلــى الســعودية‬\n‫حلســاب الغيــر مقابــل مبلــغ مالــي لقصــد الترويــج وهــم يســتحقون العقوبة‬\n‫علــى ذلــك علــى ضــوء الفقــرة ( أ ) مــن املــادة األولــى مــن قــرار ســمو‬\n‫وزيــر الداخليــة رقــم (‪ )2057‬وتاريــخ ‪1404 /5/26‬ه ـ اســتناد ًا لقــرار‬\n‫مجلــس الــوزراء رقــم(‪ )11‬وتاريــخ ‪1374/2/1‬ه ـ وإنفــاذ ًا لألمــر الســامي‬\n‫رقــم (‪ )59633‬يف ‪1432/12/9‬ه ـ وملــا ذكــر أعــاه ولكــون املدعــى‬\n‫عليهــم وافديــن ســيرحلون عــن البــاد بعــد إنفــاذ العقوبــة املقــررة بحقهــم‬\n‫ا مبقتضــى تعليمــات‬     ‫شــرع ًا وال فائــدة ترجــى مــن إطالــة ســجنهم وعم ـ ً‬\n‫ولــي األمــر التــي تقضــي بتخفيــف ســجن الوافديــن واالســتعاضة عنــه‬\n‫بكثــرة اجللــد وعــدم وجــود ســوابق علــى املدعــى عليهمــا األول والثالــث‬\n‫ووجــود ســابقة واحــدة علــى املدعــى عليــه الثانــي لــذا فقــد حكمــت علــى‬\n‫املدعــى عليهــم مبــا يلــي‪ :‬أوالً‪ /‬يعــزر كل واحــد منهــم بالســجن ملــدة‬\n‫ثالثــن شــهر ًا مــن تاريــخ إيقــاف كل واحــد منهــم يف ‪1432/9/17‬ه ـ‬\n‫ثانيــا‪ /‬يعــزر كل واحــد منهــم باجللــد بخمســمائة جلــدة علنـ ًا مفرقة كل‬\n‫دفعــة خمســون جلــدة بــن الدفعــة واألخــرى عشــرة أيــام ثالثــا‪ /‬يدفــع‬\n‫كل واحــد منهــم غرامــة ماليــة قدرهــا خمســة آالف ريــال تــودع بيــت‬\n‫مــال املســلمني رابع ـاً‪ /‬يبعــدون عــن البــاد جميعــا بعــد إنفــاذ العقوبــة‬\n‫املقــررة بحقهــم شــرع ًا وال يســمح لهــم بالدخــول إليهــا عــدى مــا تســمح‬\n\n\n                                                                                    ‫‪294‬‬\n\f      ‫بــه تعليمــات احلــج والعمــرة هــذا مــا حكمــت بــه وبعرضــه علــى الطرفــن‬\n      ‫قــرر املدعــى عليهــم القناعــة وطلــب املدعــي العــام اســتئناف احلكــم‬\n      ‫مكتفيـ ًا بالئحــة االدعــاء العــام وأمــرت بتنظيــم القــرار الــازم مبوجبــه‬\n      ‫ورفعــه حملكمــة االســتئناف مبنطقــة عســير لدراســته وإبــداء مــا تــراه‬\n      ‫نحــوه وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                      ‫‪1434/10/8‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة القائــم بعمــل رئيــس احملكمــة اجلزائيــة بنجــران‬\n      ‫برقــم ‪ 332173349‬وتاريــخ ‪1434/2/18‬ه ـ املرفــق بهــا القــرار‬\n      ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪..... /‬برقــم ‪3411918‬‬\n      ‫وتاريــخ ‪1434/1/13‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد كل مــن ‪/‬‬\n      ‫‪ .....‬و ‪ (.....‬ســعودي اجلنســية ) يف قضيــة ( ســب وشــتم ) علــى الصفــة‬\n      ‫املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n      ‫فيــه وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n      ‫املعاملــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                                ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪295‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":290,"source_page_end":295,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"51c6b01629e097ea599d814e12a94fc51012017d2914c8cf4c6cf872a8d237f2","normalized_text_hash":"42ec75f16e1271e7e460f9af57d8c6181f24c8cea688548efe7c0e1effeebc25","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p290-34330070"},{"id":"ace0bcf3-2480-5060-a6ec-48431a258370","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر - إقرار بالترويج -إنكار تعاطي احلشيش -احلدود تدرأ بالشبهات -عدم إطالة سجن األجنبي -تعزير بالسجن واجللد والغرامة .","document_number":"3433346","case_number":"33707977","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/9","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر - إقرار بالترويج -إنكار تعاطي احلشيش -احلدود تدرأ بالشبهات -عدم إطالة سجن األجنبي -تعزير بالسجن واجللد والغرامة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3433346:‬تاريخه ‪1434/2/9:‬هـ‬\n                  ‫رقم الدعوى ‪33707977:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3464580‬تاريخه‪1434/03/17:‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬تعاطــي احلشــيش املخــدر ‪-‬‬\n‫إقــرار بالترويــج ‪ -‬إنــكار تعاطــي احلشــيش ‪ -‬احلــدود تــدرأ بالشــبهات‬\n‫‪ -‬عــدم إطالــة ســجن األجنبــي ‪ -‬تعزيــر بالســجن واجللــد والغرامــة ‪.‬‬\n\n\n\n                                          ‫‪ -1‬اإلقرار حجة معبرة شرع ًا‬\n             ‫‪ -2‬املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج احلشــيش املخــدر‬\n‫وتعاطيــه‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه‬\n‫بعقوبــة الســجن واإلبعــاد ومصــادرة الهاتــف اجلــوال وعــدم صــرف‬\n‫الشــريحة لنفــس املشــترك ‪ ،‬مت القبــض علــى املدعــى عليــه بعــد إخباريــة‬\n‫مفادهــا أن املدعــى عليــه يقــوم بترويــج احلشــيش املخــدر ومت التنســيق‬\n‫مــع أحــد املصــادر الســرية لإليقــاع بــه متلبسـ ًا وبعــد االتفــاق بــن املصــدر‬\n‫واملــروج علــى املوقــع وعنــد اللقــاء بينهمــا مت القبــض علــى املدعــى عليــه‬\n‫بعــد عمليــة االســتالم والتســليم ‪ ،‬وأقــر املدعــى عليــه بالترويــج وأنكــر‬\n‫تعاطــي احلشــيش ‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر‬\n‫املدعــى عليــه بالســجن واجللــد والغرامــة ومصــادرة اجلــوال وحجــب‬\n\n                                                                                        ‫‪296‬‬\n\f      ‫الشــريحة مــن املشــترك وإبعــاده عــن البــاد بعــد انتهــاء محكوميتــه‪،‬‬\n      ‫وصــدق‬‫قنــع املدعــى عليــه وقــرر املدعــي العــام االعتــراض بالئحــة ُ‬\n                                         ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ ..........‬وتاريــخ ‪1433/12/27‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪ .............‬وتاريــخ ‪ 1433/12/27‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافــق‪ 1434/01/20‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n      ‫‪ 11‬وفيهــا إدعــى املدعــي العــام ‪..........‬ســعودي مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ..........‬والتعميــد رقــم ‪ ......‬يف ‪1432/6/12‬ه ـ وادعــى علــى ‪...........‬‬\n      ‫مــن النيجــر مبوجــب اقامــة رقــم ‪ ..........‬أوقــف بتاريــخ ‪1433/11/17‬ه ـ‬\n      ‫وأحيــل للســجن العــام قائــا يف حتريــر دعــواه أنــه باإلطــاع علــى‬\n      ‫احملضــر املعــد مــن قبــل إدارة مكافحــة املخــدرات باملدينــة بتاريــخ‬\n      ‫‪1433/11/16‬ه ـ بنــاء علــى اإلخباريــة مــن أحــد مصادرهــم الســرية‬\n      ‫عــن وجــود شــخص أســمر البشــرة يدعــى ‪ ...‬ويســكن يف حــي ‪ ....‬يقــوم‬\n      ‫بترويــج احلشــيش وباإلتصــال علــى جوالــه رقــم (‪ ).......‬لإلتفــاق معــه علــى‬\n      ‫شــراء حشــيش مببلــغ مئتــن ريــال وافــق علــى ذلــك وباحلضــور لــه باملنطقة‬\n      ‫املركزيــة وإجتــه املصــدر برفقــة الفرقــة القابضــة بعــد اإلتفــاق معــه‬\n      ‫عنــد فنــدق ‪ ....‬وبعــد حوالــي عشــر دقائــق حضــر شــخص أســمر البشــرة‬\n      ‫واحتــك مــع املصــدر وأعطــى اإلشــارة الدالــة علــى إمتــام العمليــة وجــرى‬\n      ‫القبــض عليــه واتضــح أنــه يدعــى ‪ .............‬نيجيــري اجلنســية وبتفتيشــه‬\n\n‫‪297‬‬\n\f‫شــخصيا عثــر يف جيــب ثوبــه العلــوي عــل مبلــغ مالــي ومبطابقتــه اتضــح‬\n‫أنــه املبلــغ احلكومــي املعــد لكشــف القضيــة وقــدره مئتــا ريــال كمــا‬\n‫عثــر معــه علــى جــواالت مــن نــوع ‪ ......‬اتضــح أن أحدهمــا هــو اجلــوال الذي‬\n‫مت التفــاوض معــه لعمليــة الترويــج وكان يحمــل نفــس الرقــم الــذي مت‬\n‫اإلتصــال عليــه ويحمــل رقــم مصنعــي (‪ )............‬وقــد ســلم املصــدر الــذي‬\n‫قــام بــدور املشــتري قائــد الفرقــة قطعــة ســوداء اللــون بلــغ وزنهــا أربعــة‬\n‫جرامــات يشــتبه أن تكــون مــن مــادة احلشــيش املخــدر وباســتجواب‬\n‫املدعــى عليــه إعتــرف بترويــج قطعــة بلــغ وزنهــا أربعــة جرامــات مــن‬\n‫احلشــيش املخــدر مببلــغ مئتــي ريــال وهــذه أول مــرة يقــوم بعمليــة الترويــج‬\n‫واعتــرف بتعاطيــه لنوعهــا مــن الســابق وقــد أثبــت التقريــر الكيميائــي‬\n‫الشــرعي رقــم (‪.....‬ك م ) لعــام ‪1433‬ه ـ إيجابيــة العينــة ( للحشــيش‬\n‫املخــدر ) وهــي مــن املــواد اخلاضعــة للرقابــة وانتهــى التحقيــق إلــى إتهامــه‬\n‫بترويــج قطعــة تــزن (‪ )4‬جــم أربعــة جرامــات مــن احلشــيش املخــدر عــن‬\n‫طريــق البيــع وتعاطيــه لنوعهــا مــن الســابق واملجرم على ذلــك وفقا للمادة‬\n‫الثالثــة الفقــرة الثانيــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫الصــادر باملرســوم امللكــي رقــم م‪ 39/‬يف ‪1426/7/8‬ه ـ وذلــك لالدلــة‬\n‫التاليــه ‪ -1‬ماجــاء يف محضــر القبــض ‪ -2‬ماجــاء يف إعترافــه ‪ -3‬ماجــاء‬\n‫يف التقريــر الكيميائــي الشــرعي وحيــث أن ماأقــدم عليــه املذكــور‬\n‫فعــل محــرم ومعاقــب عليــه شــرعا ونظامــا أطلــب إثبــات ماأســند اليــه‬\n‫واحلكــم عليــه وفقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫املنــوه بالعقوبــات التاليــه ‪ -1‬عقوبــة الســجن الــواردة يف املــادة (‪)38‬‬\n‫الفقــرة األولــى ‪ -2‬عقوبــة اإلبعــاد التكميليــة الــواردة يف املــادة (‪)56‬‬\n‫الفقــرة الثانيــة ‪ -3‬مصــادرة اجلــوال املضبــوط مــع املتهــم والــذي يحمــل‬\n\n\n                                                                                       ‫‪298‬‬\n\f      ‫الرقــم املصنعــي رقــم (‪ )......‬املســتخدم يف عمليــة البيــع إســتنادا للمــادة‬\n      ‫(‪ )53‬الفقــرة األولــى مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫وعــدم صــرف الشــريحة لنفــس املشــترك إســتنادا لتعميــم وزيــر الداخليــة‬\n      ‫رقــم ‪ 9798‬وتاريــخ ‪1428/2/10‬ه ـ وبســؤال املدعــى عليــه قــال ماذكره‬\n      ‫املدعــي العــام مــن بيعــي للحشــيش بالنوعيــة املذكــورة يف الدعــوى‬\n      ‫صحيــح وهــي أول مــرة وال ســوابق علــي هكــذا أجــاب وبســؤال املتهــم‬\n      ‫عــن التعاطــي أجــاب أنكــر التعاطــي وبســؤاله ملــاذا اعترفــت لــدى هيئــة‬\n      ‫التحقيــق أجــاب احلقيقــه أنــي ال أتعاطــى وعليــه وبنــاء على ماجــاء بالئحة‬\n      ‫االتهــام والتــي انتهــى فيهــا التحقيــق الــى توجيــه االتهــام الــى ‪ .....‬اجلنســية‬\n      ‫النيجــر ‪ 27‬ســنه بترويــج قطعــة تــزن أربعــة جرامــات من احلشــيش املخدر‬\n      ‫بطريــق ا لبيــع وتعاطيــه لنوعهــا مــن الســابق ولكــون ماأقــدم عليــه فعــل‬\n      ‫محــرم شــرعا ومعاقــب عليــه شــرعا ونظامــا طلــب املدعــي العــام إثبــات‬\n      ‫ماأســند اليــه واحلكــم عليــه وفــق املــادة (‪ )1/38‬واملــادة (‪ )2/56‬مــن‬\n      ‫نظــام مكافحــة املخــدرات ومصــاردة اجلــوال ذي الرقــم املصنعــي (‪)......‬‬\n      ‫املســتخدم يف اجلرميــة وعــدم صــرف الشــريحة لنفــس املشــترك وبنــاء‬\n      ‫علــى مــا أجــاب بــه املتهــم حيــث أعتــرف مبــا نســب اليــه مــن بيــع احلشــيش‬\n      ‫املخــدر ومبــا أن اإلقــرار حجــة معتبــرة شــرعا فيعامــل مبتقضــى إقــراره‬\n      ‫املعتبــر شــرعا وبنــاء علــى التقريــر الكيميائــي الشــرعي بإيجابيــة عينــة‬\n      ‫ماضبــط للحشــيش املخــدر وحيــث أنكــر مانســب اليــه مــن تعاطــي‬\n      ‫احلشــيش املخــدر يف أقوالــه أمــام احملكمــة فــإن ذلــك يعــد مــن بــاب‬\n      ‫الرجــوع يف االقــرار الــذي يــدرأ احلــد فعيــزر علــى التعاطــي وحيــث أن‬\n      ‫املتهــم أجنبــي عــن البــاد وال ســوابق مســجلة عليــه فــإن احملكمــة‬\n      ‫ســتعمل بحقــه نــص املــادة الســتني مــن نظــام مكافحــة املخــدرات إذ‬\n\n\n‫‪299‬‬\n\f‫الطائــل مــن وراء ســجنه مــع احلكــم بإبعــاده مــن أجــل ماتقــدم حكمــت‬\n‫بإدانــة املتهــم مبــا نســب اليــه واحلكــم بســجنه ســنتني إعتبــارا مــن مــدة‬\n‫توقيفــه وبتغرميــه الــف ريــال وبجلــده مائــه وعشــرين جلــده دفعــة واحــدة‬\n‫وبإبعــاده عــن البــاد بعــد تنفيــذ العقوبــة ومبصــادرة اجلــوال ذي الرقــم‬\n‫املصنعــي (‪ )............‬وجــب الشــريحه عــن املشــترك وبإتــاف املــواد‬\n‫املخــدرة احملــرزة علــى ذمــة القضيــة وبجلــده تســعا وســبعني جلــده تعزيــرا‬\n‫عــن تعاطــي احلشــيش املخــدر بــذا صــدر احلكــم وأفهــم حســب األصــول‬\n‫فقــرر املتهــم قناعتــه وقــرر املدعــي العــام اإلعتــراض بالئحــه وصلى اهلل‬\n‫علــى ســيدنا ونبينــا محمــد وعلــى الــه وصحبــه حــرر يف ‪1434/02/09‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد لــدي انا ‪ ............‬رئيس احملكمة اجلزائية باملدينة‬\n‫املنــورة والقائــم بعمــل القاضــي ‪ ............‬أثنــاء إجازتــه ففــي يــوم االربعــاء‬\n‫املوافــق ‪1434/4/3‬ه ـ افتتحــت اجللســة الســاعة الثامنــة والنصــف‬\n‫صباحــا افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة اإلســتئناف‬\n‫مبكــة املكرمــة بالرقــم ‪ ...........‬يف ‪1434/3/27‬ه ـ وبرفقــه احلكــم‬\n‫الصــادر مــن فضيلتــه بالرقــم ‪ .............‬يف ‪1434/2/9‬ه ـ واملتضمــن‬\n‫املصادقــة علــى احلكــم بالقرار رقــم ‪ ...........‬يف ‪1434/3/17‬هـ واملتعلقة‬\n‫باملتهــم ‪ ...........‬ولكــي ال يخفــى جــرى التهميــش حــرر يف ‪1434/4/6‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ -:‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثانيــة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫برقــم‪ ..........‬وتاريــخ‬      ‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة‬\n‫‪1434/2/27‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪......... /‬‬\n‫القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪6............‬وتاريــخ‬\n\n\n                                                                                           ‫‪300‬‬\n\f      ‫‪1434/2/9‬ه ـ ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪ .......... /‬نيجيــري‬\n      ‫اجلنســية ‪ ،‬املتهــم يف قضيــة مخــدرات ‪ ،‬احملكــوم فيــه مبــا دون باطنــه‬\n      ‫‪ .‬وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت‬\n      ‫املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                              ‫آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪301‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":296,"source_page_end":301,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e895cf36af426f06ffbfab0a4a661e1541144eb0513740a1332444d7c833a367","normalized_text_hash":"f8cdbe93cde8ecd291a6e10342e48ea377dce6fc952ba58c6d9ce34be55a834b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p296-3433346"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

